begin;
alter table public.fa_sign_documents
  drop constraint if exists fa_sign_documents_catalog_slot_check;
alter table public.fa_sign_documents
  add constraint fa_sign_documents_catalog_slot_check
  check (catalog_slot between 1 and 257);

insert into public.fa_signs (slug, name) values ('gbe-medji', 'Gbé-Mèdji') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 1, 'signe_mere', 1, '{"slug":"gbe-medji","nom":"Gbé-Mèdji","ordre":1,"type":"signe_mere","position":"1er signe-mère","sexeSymbolique":"Masculin","maison":"Première maison","divinites":"Mahu, Lissa, Dan, Gbadu, Hêbiosso, Sakpata","feuilles":"Fenie (manioc), Kotamà, Zuno, surtout Affamà","couleurs":"Blanc principalement ; accepte aussi les autres couleurs.","profil":["Le porteur de Gbé-Mèdji connaît un peu de souffrance mais possède une forte capacité de réussite. Il peut faire suivre une bonne action d’une mauvaise, se montrer audacieux et exercer une grande autorité.","Il peut devenir un bon guerrier ou lutteur, acquérir richesse et gloire et réussir dans ce qu’il entreprend. Le signe le décrit comme juste, honnête et très fort. Il peut cependant être égoïste malgré une grande renommée.","La descendance est un domaine sensible : le texte associe au signe la perte d’une ou plusieurs filles chez l’homme et, chez la femme, la possibilité de perdre un fils."],"devises":[{"ordre":1,"titre":"La terre couverte d’eau, les herbes et les montagnes","sens":"La création et la stabilité sont mises en avant : les montagnes s’élèvent comme obstacles et le vent ne peut les renverser."},{"ordre":2,"titre":"Le chemin de la mort n’est jamais fermé au chien ni à Aklassu","sens":"La devise renvoie au flair du chien face à la mort et à la perception d’un danger."},{"ordre":3,"titre":"Aklassu descend sur un corps sans vie","sens":"La devise évoque la présence du vautour auprès du cadavre et l’accomplissement d’un événement déjà survenu."},{"ordre":4,"titre":"La foudre n’atteint pas Aguidigbahun au cœur de la montagne","sens":"Le favi est présenté comme protégé contre certains dangers."}],"interdits":["Vin de palme Attan","Chien","Léopard","Éléphant","Petit oiseau Titigoti (moineau)","Aguidigbahun","Aklassu","Honsu-Honsu","Coq"],"prescriptions":["Faire les sacrifices prescrits","Adorer Dan-Ayidohuèdo","Adorer Lissa","Adorer Tohossou"],"synthese":"Gbé-Mèdji associe autorité, force, honnêteté, richesse, gloire et réussite. Le porteur doit toutefois respecter ses interdits et les prescriptions liées à Dan-Ayidohuèdo, Lissa et Tohossou."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
from public.fa_signs where slug = 'gbe-medji'
on conflict (fa_sign_id) do update
set catalog_slot = excluded.catalog_slot,
    kind = excluded.kind,
    mother_order = excluded.mother_order,
    content = excluded.content,
    source = excluded.source,
    status = excluded.status,
    updated_at = now();

insert into public.fa_signs (slug, name) values ('yekou-medji', 'Yèkou-Mèdji') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 2, 'signe_mere', 2, '{"slug":"yekou-medji","nom":"Yèkou-Mèdji","ordre":2,"type":"signe_mere","position":"2e signe-mère","sexeSymbolique":"Féminin","maison":"Deuxième maison","divinites":"Kututo, Gbadu, Tohossou, Dan, Sakpata, Hêbiosso","feuilles":"Sisrèmà, Gbagbada, Ahwimà, Yasséakù","couleurs":"Noir.","profil":["Yèkou-Mèdji décrit une personne qui respecte sa parole, digne de confiance, mais qui peut être bavarde et indiscrète.","Elle est très intelligente, peut devenir un bon chef et obtenir gloire et honneur. Elle est populaire mais peut connaître des déceptions.","Le porteur voyage beaucoup et passe peu de temps dans sa ville natale. Il peut être turbulent et fort, vivre longtemps mais être souvent malade."],"devises":[{"ordre":1,"titre":"La nuit est tombée et les trous deviennent effrayants","sens":"Yèkou est relié à la nuit et au monde des morts, dont il est présenté comme maître."},{"ordre":2,"titre":"La minceur de l’arbre, le nœud de la corde et la peau du crocodile","sens":"Ces caractéristiques ne détruisent pas l’objet ou l’animal : le consultant doit échapper à la maladie, aux accidents et aux ennemis."},{"ordre":3,"titre":"Le poisson tombé du ciel à Alangba","sens":"Ce qui est pris pour la mort ne l’est pas nécessairement : le favi peut être délivré d’un mal."},{"ordre":4,"titre":"L’œil ne voit pas à travers un tissu noir dans la nuit noire","sens":"La mort, les accidents et les ennemis ne doivent pas atteindre le consultant si les sacrifices prescrits sont correctement exécutés."}],"interdits":["Nu Ku Ku : animaux ou oiseaux trouvés morts","Nourritures offertes à Kututo ou au culte des ancêtres","Fruit noir de l’arbre fô","Vin de palme","Pagnes ou vêtements rouges","Brûler/fumer les fourmis noires","Utiliser des épines ou du bois d’arbre épineux pour les sacrifices","Honsu-Honsu","Aklassu","Dègbo","Afanku","Chat","Coq"],"prescriptions":["Faire des offrandes à Kututo, les morts et les ancêtres","Adorer Dan","Adorer Tohossou","Adorer Sèovi"],"synthese":"Yèkou-Mèdji unit intelligence, autorité, voyage, confiance et longévité, mais aussi indiscrétion, déceptions et santé fragile. Le respect des ancêtres et de Kututo occupe une place importante."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
from public.fa_signs where slug = 'yekou-medji'
on conflict (fa_sign_id) do update
set catalog_slot = excluded.catalog_slot,
    kind = excluded.kind,
    mother_order = excluded.mother_order,
    content = excluded.content,
    source = excluded.source,
    status = excluded.status,
    updated_at = now();

insert into public.fa_signs (slug, name) values ('woli-medji', 'Woli-Mèdji') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 3, 'signe_mere', 3, '{"slug":"woli-medji","nom":"Woli-Mèdji","ordre":3,"type":"signe_mere","position":"3e signe-mère","sexeSymbolique":"Masculin","maison":"Troisième maison","divinites":"Gu, Aguê, Lissa, Loko, Tohossou","feuilles":"Wélékpékpé","couleurs":"Brun tirant vers le rouge.","profil":["Le porteur de Woli-Mèdji peut gagner l’estime de son entourage. Son enfance peut être dure, tandis que sa vie d’adulte et sa situation professionnelle peuvent devenir brillantes.","Il est associé à la réalisation des projets, à une recherche spirituelle ou religieuse étendue et à une autorité incontestable dans la famille.","Il peut obtenir une place de choix dans sa famille et sa ville natale."],"devises":[{"ordre":1,"titre":"La prospérité de Gbodo dépend de son roi","sens":"Le bonheur et la réussite du consultant dépendent fortement de lui-même."},{"ordre":2,"titre":"Les bonnes choses existent mais nul ne pénètre Gbodo sans danger","sens":"La richesse et les avantages existent, mais certaines conditions doivent être respectées."},{"ordre":3,"titre":"Si l’hyène crie, c’est qu’elle cherche à manger","sens":"Le favi n’est pas destiné à la pauvreté."},{"ordre":4,"titre":"L’oranger planté par l’un est déraciné par un autre","sens":"La santé peut varier fortement : un jour grave, le lendemain bénin ; le favi peut frôler la mort puis se relever."},{"ordre":5,"titre":"Que Gbodo soit bon ou mauvais, l’hyène trouve quelque chose à manger","sens":"Ce que Dieu a donné à quelqu’un finit par lui parvenir."}],"interdits":["Tout animal trouvé mort ou décapité","Adjagbé","Vin de palme","Chien","Girafe","Hyène","Éléphant","Coq"],"prescriptions":["Adorer Gu","Adorer Tohossou","Adorer Kututo","Respecter les sacrifices indiqués, notamment viande et chapeau"],"synthese":"Woli-Mèdji est un signe de progression : difficultés au départ, puis réussite, autorité et reconnaissance. Le porteur est appelé à trouver sa place par son action et le respect des prescriptions."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
from public.fa_signs where slug = 'woli-medji'
