insert into public.fa_signs (slug, name) values ('di-medji', 'Di-Mèdji') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 4, 'signe_mere', 4, '{"slug":"di-medji","nom":"Di-Mèdji","ordre":4,"type":"signe_mere","position":"4e signe-mère","sexeSymbolique":"Féminin","maison":"Quatrième maison","divinites":"Nà-Kinnessi, Jumeaux, Gbadu, Tohossou, Lissa","feuilles":"Désréguê / Désréssiguê","couleurs":"Noir et bigarré ; jaune et rouge parfois pour certains sacrifices aux femmes.","profil":["Di-Mèdji décrit une personne de bonne disposition conjugale, mais qui peut traverser beaucoup de peines et de difficultés. Elle peut conserver une apparence joyeuse tout en cachant ses souffrances.","Le porteur possède une grande conscience professionnelle, aime les autres sans tenir compte de leur rang social et peut gagner la confiance de ses amis et collaborateurs.","Le signe mentionne des contraintes morales et physiques, des difficultés judiciaires ou administratives, de la lenteur ou une incapacité momentanée à réaliser certaines choses. La vie peut être sombre au début puis brillante plus tard. Une place importante et une grande renommée sont possibles."],"devises":[{"ordre":1,"titre":"Mort, maladie, procès et grand pagne dans les épines","sens":"Le favi doit être protégé contre mort, maladie, procès et accident."},{"ordre":2,"titre":"Le léopard ne peut attraper un chien dans une cage métallique","sens":"La protection contre un danger puissant est mise en avant."},{"ordre":3,"titre":"Si une grosse viande est perdue, chercher sur le séchoir","sens":"Celui qui trouve ce signe est présenté comme malin et bien renseigné ; il faut s’en méfier, mais on peut aussi l’utiliser."},{"ordre":4,"titre":"Une rive ne peut se déplacer pour combattre l’autre","sens":"Des ennemis peuvent se trouver dans la maison du consultant sans pouvoir réellement lui nuire."}],"interdits":["Nà Nu Dà Nu : nourritures consacrées à Nà et Dà","Coq","Lièvre Azwi/Azui","Singes Zin wo, Klan, Xa/Za","Gnibu (bœuf) selon la formulation du corpus","Za-Klouékun","Éléphant","Lion","Léopard","Hyène","Alului"],"prescriptions":["Être large dans les sacrifices","Faire des sacrifices d’argent et d’autres biens","Adorer Na-hoho (Jumeaux)","Adorer Kinnessi","Adorer Tohossou"],"synthese":"Di-Mèdji associe professionnalisme, confiance, intelligence relationnelle et renommée à des lenteurs, contraintes et difficultés administratives. La trajectoire peut être difficile au départ puis favorable."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
