insert into public.fa_signs (slug, name) values ('losso-medji', 'Losso-Mèdji') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 5, 'signe_mere', 5, '{"slug":"losso-medji","nom":"Losso-Mèdji","ordre":5,"type":"signe_mere","position":"5e signe-mère","sexeSymbolique":"Masculin","maison":"Cinquième maison","divinites":"Hêbiosso, Yalodé, Dà, Nà, Gu, Tovodoun, Lissa","feuilles":"Ologoncece / Kpakléssi, Xexemà, Dindin fundin, Amàjê","couleurs":"Rouge, symbole du feu, de la foudre, de la colère, du sang et de l’accident.","profil":["Losso-Mèdji est présenté comme l’un des signes les plus redoutables. Le porteur peut être pauvre, indiscret et vindicatif, avec une tendance à appliquer littéralement la loi du talion.","Sa vie peut connaître de nombreuses vicissitudes et difficultés. Pourtant, il est persévérant, aime les autres et se confie facilement à ses camarades.","Il possède une intuition très développée. Sa réussite peut être instable, il peut faire des dépenses inutiles et entrer en opposition avec son entourage pour des questions d’intérêt. Le signe est peu favorable à l’union."],"devises":[{"ordre":1,"titre":"Quand Akpà se met en colère, tous les oiseaux s’envolent","sens":"Le favi doit faire les sacrifices nécessaires afin d’échapper aux malheurs."},{"ordre":2,"titre":"Œil rouge ne veut pas dire œil crevé","sens":"Le porteur peut souffrir des épreuves de la vie sans nécessairement en mourir."},{"ordre":3,"titre":"L’œil qui se moque du piment ne reste pas tranquille","sens":"Le favi est exposé aux accidents et ne doit pas les sous-estimer."},{"ordre":4,"titre":"Tant que l’aigle Hon vit, l’oiseau Gué ne peut être roi","sens":"Si les sacrifices sont exécutés, le favi peut être appelé à commander la maison de son père."}],"interdits":["Tout ce qui est rouge : vêtements, mobilier, bijoux, plumes Kèsè, teinture Sokpakpê","Épouser une femme très claire de teint","Épouser une Sakpatassi ou une Hêbiossossi","Singes Klan et Ajissilwé","Oiseaux Akpà, Drègbagwé, Gué, Aklassu, Ututu","Girafe Agbanlin","Fruits rouges Gogozotin et Cili vovo"],"prescriptions":["Adorer Hêbiosso","Adorer Dà","Adorer Yalodé","Adorer Gu","Faire annuellement le rite Nu kun miàn avec les éléments prescrits"],"synthese":"Losso-Mèdji est marqué par l’intensité : intuition, persévérance et possibilité de commandement, mais aussi accidents, conflits, instabilité et forte symbolique du rouge."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
from public.fa_signs where slug = 'losso-medji'
