insert into public.fa_signs (slug, name) values ('winlin-medji', 'Winlin-Mèdji') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 6, 'signe_mere', 6, '{"slug":"winlin-medji","nom":"Winlin-Mèdji","ordre":6,"type":"signe_mere","position":"6e signe-mère","sexeSymbolique":"Féminin","maison":"Sixième maison","divinites":"Sakpata, Kinnessi, Tohossou, Dà, Hoho (Jumeaux), Lissa","feuilles":"Atoladola, Godokô / Gninsinkin, Mafowokà omomi","couleurs":"Wanlan-wanlan : moucheté / bigarré.","profil":["Le porteur de Winlin-Mèdji peut être brutal mais estimé par son entourage. Il souffre au début puis connaît une période plus heureuse.","Il est franc, juste et correct envers tous. Il peut devenir riche et charitable, et s’élever au-dessus de son milieu grâce à son savoir-faire et à son travail."],"devises":[{"ordre":1,"titre":"Si le piment rouge déclare la guerre au mil, le piment gagne","sens":"Si les sacrifices sont exécutés, le consultant peut toujours vaincre ses ennemis."},{"ordre":2,"titre":"Sans l’ordre de Sè Lissa, la guerre ne détruit pas un pays","sens":"Le favi doit honorer Sègbo Lissa pour être préservé du danger."},{"ordre":3,"titre":"Une natte ordinaire ne se couche pas sur une plus belle natte","sens":"Une action entreprise avec quelqu’un peut apporter des avantages mais aussi des difficultés."},{"ordre":4,"titre":"La guerre ne brise pas les rochers","sens":"Les ennemis ne peuvent rien contre le consultant."}],"interdits":["Pintade Sonu","Nourritures consacrées à Sakpata","Tous les aliments grillés","Vin de palme","Bière de mil","Bière de sorgho","Éléphant","Cheval","Hyène","Girafe","Coq","Épouser une prêtresse de Sakpata","Se baigner dans la mer","Porter des vêtements bigarrés ou de plus de deux couleurs"],"prescriptions":["Adorer Sakpata","Adorer Kinnessi","Adorer Tohossou","Faire annuellement les sacrifices prescrits"],"synthese":"Winlin-Mèdji associe justice, franchise, travail, richesse et charité à une forte protection contre les ennemis. Les interdits liés à Sakpata et aux boissons fermentées sont importants."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
from public.fa_signs where slug = 'winlin-medji'
