insert into public.fa_signs (slug, name) values ('abla-medji', 'Abla-Mèdji') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 7, 'signe_mere', 7, '{"slug":"abla-medji","nom":"Abla-Mèdji","ordre":7,"type":"signe_mere","position":"7e signe-mère","sexeSymbolique":"Masculin","maison":"Septième maison","divinites":"Lissa, Hoho (Jumeaux), Tovodun, Toyiyo, Dan","feuilles":"Davonumà","couleurs":"Bleu clair.","profil":["Le porteur d’Abla-Mèdji peut être heureux, avoir une bonne épouse et de bonnes habitudes. Il peut aussi traverser un peu de malheur, être dur ou peu aimable et connaître une maladie de courte durée, tout en ayant une longue vie.","Il est ambitieux, agit avec force et vigueur et peut triompher dans plusieurs domaines. Le signe évoque toutefois une fin de vie plus malheureuse."],"devises":[{"ordre":1,"titre":"C’est l’éventail qui sèche la sueur","sens":"Le favi est défendu contre ses ennemis."},{"ordre":2,"titre":"Le porc-épic courtise la femelle léopard et échappe au mâle","sens":"Même face à quelqu’un de plus puissant, le consultant peut triompher dans le combat engagé contre lui."},{"ordre":3,"titre":"L’homme patient devient roi du pays haoussa","sens":"Le porteur doit observer la patience dans son propre intérêt."},{"ordre":4,"titre":"La femme qui mange dans deux auges s’expose à la mort","sens":"Le signe met fortement en garde contre l’infidélité conjugale."},{"ordre":5,"titre":"Le poisson Houa tire la ressource de l’eau douce vers le rivage","sens":"Cette devise est associée aux thèmes propres au signe et à l’interdit du poisson Houa."}],"interdits":["Poisson Houa","Fruit Oussi bala","Boules d’akassa enveloppées selon la forme interdite Alô vi do gudo","Oiseaux Hluinsuvô, Agbogbo, Agàgà, Aklassu","Singes Zinvô et Klan","Rongeur Glinzin","Toutes les tortues","Dan / tous les serpents","Crocodile Lo et autres Tohossou","Hyène","Éléphant","Léopard","Antilope Tê","Coq","Vipère Amannônu","Vêtements en raphia Dêvô"],"prescriptions":["Adorer Dan","Adorer Sakpata","Faire un culte et une offrande importante d’éventail et d’argent"],"synthese":"Abla-Mèdji donne force, ambition, patience et capacité à triompher d’adversaires plus puissants. La fidélité conjugale, les interdits animaliers et le culte de Dan et Sakpata y sont importants."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
