insert into public.fa_signs (slug, name) values ('aklan-medji', 'Aklan-Mèdji') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 8, 'signe_mere', 8, '{"slug":"aklan-medji","nom":"Aklan-Mèdji","ordre":8,"type":"signe_mere","position":"8e signe-mère","sexeSymbolique":"Féminin","maison":"Huitième maison","divinites":"Hohovi (Jumeaux), Lègba, Hêbiosso, Dan, Sakpata, Tohossou","feuilles":"Agogo-ogû / Koklo dèkpadjè, Koloma, Weagbo / Asobokan","couleurs":"Rouge, noir, blanc et bleu ; préférence pour le tacheté.","profil":["Le porteur d’Aklan-Mèdji peut obtenir des honneurs, être fier, tenace, aimé de tous, mesuré et solitaire.","Il peut être mélancolique, réfléchi, très confiant en lui-même et très avare de ses biens. De nombreuses afflictions peuvent précéder un bonheur durable.","La vie peut alterner hauts et bas. La longévité est possible à condition d’une vigilance sur la santé. Deuils, douleurs, chagrins et héritages peuvent se succéder."],"devises":[{"ordre":1,"titre":"Deux morceaux de fer soudés ne peuvent être séparés","sens":"Les ennemis ne peuvent rien contre le favi."},{"ordre":2,"titre":"L’eau qui a servi à laver les mains est immédiatement jetée","sens":"Ce que les ennemis entreprennent contre le favi doit échouer."},{"ordre":3,"titre":"Le contenu du sac à cordon ne tombe pas même lorsqu’on le renverse","sens":"La devise porte un avertissement concernant le risque de fausse couche chez une femme enceinte."},{"ordre":4,"titre":"Le filet de pêche ne capture pas l’hippopotame","sens":"Le favi échappe aux dangers et aux accidents."}],"interdits":["Viande de singe","Haricot Akpakoun","Attacher soi-même des fagots de bois","Boules d’akassa enveloppées Alôvi do gudo","Toucher la liane Agbakan","Chien","Coq","Léopard","Aklassu","Buffle","Brûler du bois d’iroko"],"prescriptions":["Adorer Hoho / les Jumeaux","Adorer Lègba","Adorer Hêbiosso","Faire annuellement des offrandes aux Jumeaux"],"synthese":"Aklan-Mèdji associe honneurs, ténacité et protection à une vie marquée par des alternances, des deuils et des afflictions. Les Jumeaux, Lègba et Hêbiosso occupent une place centrale."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
