insert into public.fa_signs (slug, name) values ('guda-medji', 'Guda-Mèdji') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 9, 'signe_mere', 9, '{"slug":"guda-medji","nom":"Guda-Mèdji","ordre":9,"type":"signe_mere","position":"9e signe-mère","sexeSymbolique":"Masculin","maison":"Neuvième maison","divinites":"Gu, Lègba, Aguê, Hêbiosso, Dà, Ke","feuilles":"Lidji, Agna…","couleurs":"Rouge, noir, blanc.","profil":["Le porteur de Guda-Mèdji peut être un juge intègre, honnête et sûr de lui. Il cherche à tout connaître et agit avec vigueur.","Sa renommée peut se répandre malgré un caractère égoïste ou orgueilleux. Il peut connaître beaucoup d’ennemis, de troubles, de tourments et de contrariétés.","Le signe est peu favorable à l’union et comporte des avertissements sur la santé, les accidents inattendus et la mort subite."],"devises":[{"ordre":1,"titre":"L’arbre qui croise le métal n’a pas bonne santé","sens":"Le contact avec Gu / le métal est présenté comme porteur de risque."},{"ordre":2,"titre":"La femme du chasseur n’alerte pas le voisinage pour rien","sens":"Le désir du consultant peut se réaliser."},{"ordre":3,"titre":"Le bois courbé ne craint plus le rein","sens":"Le corpus associe cette image aux fonctions sexuelles et à un risque de déclin si les prescriptions ne sont pas respectées."},{"ordre":4,"titre":"Le couteau tranchant coupe et le sang jaillit","sens":"Le favi est présenté comme très puissant et appelé à réussir."},{"ordre":5,"titre":"Quand Lègba Adigbà est en érection, toutes les femmes sont servies","sens":"La devise reprend le thème de la puissance sexuelle et du risque de déclin ultérieur."}],"interdits":["Tortue Logozo","Antilope La","Crocodile Lo","Serpents","Fruit du faux acajou Lissè","Hibou Azéhê","Agbogbo","Lêkê-Lêkê","Manioc","Igname pilée Agu","Coq","Danser hors de chez soi","Porter le Godo ou chokoto-chaka","Creuser un trou ou une fosse","Placer un objet de Gu (arme, couteau) près du lit","Porter un poignard"],"prescriptions":["Adorer Gu","Adorer Lègba","Adorer Aguê","Faire les Vonssissa prescrits contre les accidents","Faire des offrandes à Lègba","Respecter les sacrifices de boissons et de pantalons"],"synthese":"Guda-Mèdji unit justice, force, puissance et réussite à des risques d’accident, de conflit, de santé et d’instabilité dans l’union. Gu et Lègba y jouent un rôle majeur."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
