insert into public.fa_signs (slug, name) values ('sa-medji', 'Sa-Mèdji') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 10, 'signe_mere', 10, '{"slug":"sa-medji","nom":"Sa-Mèdji","ordre":10,"type":"signe_mere","position":"10e signe-mère","sexeSymbolique":"Féminin","maison":"Dixième maison","divinites":"Gbadu, Nà, Azé, Kinnessi, Tohossou, Yalodé, Naawo, Lissa, Loko","feuilles":"Avôkanfunmà, Gnonussissi, Zomà, Zêzêmà, Ajassiafôvê","couleurs":"Rouge principalement, puis blanc et bleu.","profil":["Sa-Mèdji peut rendre le porteur heureux et grand voyageur. Après des débuts difficiles, il peut réussir et vivre loin de sa terre natale.","Le signe lui attribue une santé robuste, une fin de vie heureuse, une grande intelligence et un goût pour la recherche et les sciences occultes.","Le porteur agit avec énergie et force, peut devenir riche et prodigue, et se montre bon juge. Il ne doit pas se décourager devant les échecs : avec effort, il peut être récompensé."],"devises":[{"ordre":1,"titre":"La salive prépare la glu et la détache","sens":"Faire du mal au favi peut attirer de graves difficultés à celui qui agit contre lui."},{"ordre":2,"titre":"La nature a placé la vulve entre les deux cuisses","sens":"La devise touche au domaine sexuel et aux interdits associés."},{"ordre":3,"titre":"Je suis assis sur la chaise en bambou du devin","sens":"Le favi présente des dispositions à devenir prêtre de Fa."},{"ordre":4,"titre":"L’oiseau qui voulait se coller trouva la fortune et oublia son akàma","sens":"Le porteur peut s’enrichir mais oublier rapidement les épreuves de la pauvreté."}],"interdits":["Poulet","Tout oiseau considéré comme sorcier","Nourritures offertes à Nà","Sorgho Abôkun","Éléphant","Afyanku","Chien","Léopard","Coq","Chat","Vin de palme","Approcher le coton du feu","Utiliser la graine Kpédjélékun et les feuilles d’iroko","Pratiquer la sorcellerie","Se porter garant d’une dette entre deux personnes","Pour l’homme : regarder les organes sexuels de son épouse","Pour la femme : avoir des rapports sexuels le jour"],"prescriptions":["Adorer Nà","Adorer Tohossou","Adorer Yalodé","Adorer Sakpata","Faire les sacrifices Hê nà","Élever le perroquet","Offrir annuellement du bois de chauffe"],"synthese":"Sa-Mèdji associe intelligence, voyages, richesse, énergie et dispositions pour le Fa à des interdits très précis sur le plan alimentaire, rituel, social et sexuel."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
