insert into public.fa_signs (slug, name) values ('ka-medji', 'Ka-Mèdji') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 11, 'signe_mere', 11, '{"slug":"ka-medji","nom":"Ka-Mèdji","ordre":11,"type":"signe_mere","position":"11e signe-mère","sexeSymbolique":"Masculin","maison":"Onzième maison","divinites":"Tohossou, Hohovi (Jumeaux), Hêbiosso, Lissa, Gu, Loko, Dà","feuilles":"Selevikè / Srèsrèvikè","couleurs":"Noir, rouge et bleu ; apprécie aussi le tacheté.","profil":["Ka-Mèdji associe ambition, intelligence, esprit belliqueux, persévérance, ruse face aux obstacles, bonheur, richesse, famille nombreuse et protection contre les ennemis.","Le porteur peut cependant être irréfléchi, dédaigneux envers les autres et connaître de nombreux heurts avec son entourage. Une fin subite ou malheureuse est également annoncée."],"devises":[{"ordre":1,"titre":"La petite calebasse tombe dans l’eau sans s’immerger","sens":"Si le favi tombe dans un malheur quelconque, il peut s’en tirer facilement."},{"ordre":2,"titre":"Celui qui est dans l’eau jusqu’au cou ne cherche plus de calebasse pour boire","sens":"Le bonheur du favi dépend aussi de lui-même."},{"ordre":3,"titre":"L’ancre mouille et la pirogue s’arrête","sens":"Après les vicissitudes, le consultant peut trouver son bonheur ; second sens : protection de la grossesse si les prescriptions sont respectées."},{"ordre":4,"titre":"Le roi haoussa ne meurt jamais autrement que riche","sens":"Le favi peut finir riche."},{"ordre":5,"titre":"Tous les arbres se noient, mais le bambou résiste","sens":"Le favi peut échapper à ses ennemis."}],"interdits":["Azin gokwin","Poisson fumé et recourbé Hué hiha","Patate douce","Serpents de toute espèce","Crocodile","Pangolin Lihui","Escargot","Oiseau Agbogbo","Singes Haa, Klan, Zinwo"],"prescriptions":["Adorer Tohossou","Adorer Dà","Adorer Hoho / les Jumeaux","Adorer Gu","Faire les offrandes liées à l’eau (Tohossou gban, Dangban)","Faire annuellement de l’aumône aux forgerons","Faire des sacrifices aux Jumeaux"],"synthese":"Ka-Mèdji est un signe de résistance et de persévérance. Le porteur peut connaître les vicissitudes puis trouver stabilité, bonheur et richesse, tout en devant maîtriser son caractère belliqueux."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
