insert into public.fa_signs (slug, name) values ('trukpin-medji', 'Trukpin-Mèdji') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 12, 'signe_mere', 12, '{"slug":"trukpin-medji","nom":"Trukpin-Mèdji","ordre":12,"type":"signe_mere","position":"12e signe-mère","sexeSymbolique":"Féminin","maison":"Douzième maison","divinites":"Sakpata, Hohovi (Jumeaux), Lègba, Hêbiosso, Dan, Tohossou","feuilles":"Non précisées dans la fiche structurée","couleurs":"Rouge, noir, blanc et bleu ; préférence pour le tacheté.","profil":["Trukpin-Mèdji associe protection, équité, intelligence, autorité, voyages, difficultés sentimentales, lenteur matérielle, hésitation et difficultés liées à la descendance.","Le porteur peut être un excellent juge et agir avec équité. Le début de sa vie peut être malheureux et la fin bonne. Il peut devenir chef d’une grande puissance, être rarement malade et beaucoup voyager.","Le domaine de la descendance est très sensible : le corpus mentionne des enfants morts-nés et peu ou pas d’enfants vivants. Les réalisations matérielles peuvent être lentes à cause d’une hésitation persistante liée à la crainte ou à trop de scrupules."],"devises":[{"ordre":1,"titre":"On ne peut tresser la terre ni saisir le soleil","sens":"Personne ne pourra nuire au porteur si les sacrifices nécessaires sont faits."},{"ordre":2,"titre":"La tête d’un enfant ne supporte pas le poids de la terre","sens":"Une menace de mort peut concerner un membre de la famille ; le corpus prescrit Vonssissa Kudiô."},{"ordre":3,"titre":"La case plafonnée est jolie, mais il y fait très chaud","sens":"Une situation peut être belle en apparence tout en comportant une difficulté intérieure."},{"ordre":4,"titre":"La femme est à peine enceinte que l’enfant est déjà à terre avant terme","sens":"Le signe porte un avertissement fort concernant les pertes de grossesse."},{"ordre":5,"titre":"La rivière en crue s’étale largement sur les herbes","sens":"Le favi peut être comblé de biens, mais de maux aussi."}],"interdits":["Gombo Févi","Papaye","Cucurbitacée Ayikpè","Coq","Pintade","Serpents","Léopard Kpô","Sorgho","Éléphant","Hyène Hia","Oisillon Drégbagwé","Tous les oiseaux utilisés en sorcellerie","Tous les singes","Chien","Chat"],"prescriptions":["Adorer Sakpata","Adorer Nà","Adorer Hoho / les Jumeaux","Faire Vonssissa Enagni ho mê Zon pour les maux du ventre","Faire annuellement des offrandes de bananes et de papayes"],"synthese":"Trukpin-Mèdji est un signe de grande intelligence, d’équité, de protection et d’autorité, mais marqué par de fortes épreuves concernant la famille, la descendance, l’amour et les réalisations matérielles."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
