insert into public.fa_signs (slug, name) values ('tula-medji', 'Tula-Mèdji') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 13, 'signe_mere', 13, '{"slug":"tula-medji","nom":"Tula-Mèdji","ordre":13,"type":"signe_mere","position":"13e signe-mère","sexeSymbolique":"Masculin","maison":"Treizième maison","divinites":"Lègba, Dan, Ajaguna, Lissa, Hoho, Gu, Tohossou","feuilles":"Alafya / Fifamà, Déùmà","couleurs":"Toutes les couleurs ; préférence pour le bleu, le blanc, l’or et le tacheté.","profil":["Tula-Mèdji est un signe de mouvement, d’autorité et de puissance sociale. Le porteur peut beaucoup voyager, devenir un chef influent, travailler avec persévérance et exercer de grandes responsabilités.","Il peut être un excellent administrateur, jouir d’une grande autorité et améliorer sa condition de vie. Mais le bavardage, l’indiscrétion, le dédain, la jalousie des prérogatives et certaines relations avec les femmes peuvent créer de sérieux problèmes.","Le signe insiste fortement sur la maîtrise de la parole : le porteur peut améliorer sa condition puis la gâcher par ses propres paroles."],"devises":[{"ordre":1,"titre":"Un musulman ne peut en adorer un autre","sens":"Le favi n’a pas à se soucier du rang social de ses interlocuteurs."},{"ordre":2,"titre":"Le même bec construit et défait le nid","sens":"Le porteur peut améliorer sa condition puis la gâcher par ses propres paroles."},{"ordre":3,"titre":"Le soleil ne peut attraper la lune pour la torturer","sens":"L’ennemi ne pourra rien contre le consultant ; il bénéficie d’une forme de sécurité."},{"ordre":4,"titre":"Ala fia - Allah Kubaru","sens":"Le favi doit faire de nombreuses aumônes (Saala)."},{"ordre":5,"titre":"Même usé, l’indigo teint encore l’étoffe","sens":"Le favi ne sera jamais tout à fait malheureux."}],"interdits":["Écureuil Don","Maïs grillé","Tabac","Porc","Igname pilée Agù","Tourterelle Hwélé","Coq","Hyène Hia","Tous les singes","Vin de palme","Indiscrétion","Port de couteau ou canif dans la poche","Port du burnous Agbada"],"prescriptions":["Faire de nombreuses aumônes Saala","Avoir chez soi un petit autel de sable de type utilisé pour la prière musulmane","Adorer Dan","Adorer Lègba","Adorer Lissa","Faire Vonsissa-E na bla dan gban","Faire chaque année des offrandes d’akassa ou bouillie de maïs sucrée et de poissons"],"synthese":"Tula-Mèdji donne voyage, influence, autorité, travail et protection. Son danger majeur réside dans la parole incontrôlée et l’indiscrétion, capables de défaire ce que le travail a construit."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
