insert into public.fa_signs (slug, name) values ('lete-medji', 'Lètè-Mèdji') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 14, 'signe_mere', 14, '{"slug":"lete-medji","nom":"Lètè-Mèdji","ordre":14,"type":"signe_mere","position":"14e signe-mère","sexeSymbolique":"Féminin","maison":"Quatorzième maison","divinites":"Sakpata, Hêbiosso, Nà, Gbadu, Dè, Lissa, Azovowema","feuilles":"Awiimà, Gnissinkin, Akaya, Tohossou","couleurs":"Rouge, noir, gris, bleu, blanc.","profil":["Lètè-Mèdji décrit une personne beaucoup considérée par sa famille et ses parents, appelée à occuper une place importante dans sa ville natale.","Le porteur est courageux, têtu et n’a peur de rien, pas même de la mort. Il est ambitieux, très viril, énergique, bouillant, impatient et animé d’une grande confiance en lui-même.","Il peut être souvent malade malgré une longévité probable. Son caractère combatif peut provoquer heurts, luttes passionnelles et parfois le dédain de son entourage. Le domaine sentimental est difficile, avec possibilité de veuvage. Le cœur et les passions peuvent dominer l’intérêt général."],"devises":[{"ordre":1,"titre":"Le soleil ardent n’éteint pas l’ombre","sens":"Le favi conserve ce qu’il possède ; ses ennemis ne peuvent rien lui arracher."},{"ordre":2,"titre":"Le martèlement de l’enclume finit par l’enfoncer dans la terre","sens":"Avec courage et respect des prescriptions, le consultant peut venir à bout de ses ennemis."},{"ordre":3,"titre":"La terre brave la mort et survit","sens":"Le favi est protégé."},{"ordre":4,"titre":"Tout ce qui vient d’en haut pose la tête sur la terre","sens":"Le favi peut savoir ce qui se passe autour de lui, en bien comme en mal."},{"ordre":5,"titre":"L’huile paraît claire en surface mais possède un dépôt noir au fond","sens":"Les apparences peuvent cacher un danger inattendu ; le favi doit rester vigilant."}],"interdits":["Pâte Adjagbé","Lan kùkù : tout animal trouvé mort","Agbanlin","Zùngbô","Mil / sorgho Abôkùn","Pintade Sonù","Pâte de farine de maïs Adan","Mets Kuluwé","Bananes Kokwé alôgli","Oiseau Awajihè","Tous les interdits de Sakpata","Nànù","Dannù","Fruit blanc de l’arbre gbêgbê","Fruit du nété Ahwa","Liquide Adi sin utilisé pour l’indigo","Tous les singes","Casser les termitières","Bois de Honsu kokwé","Serpent Amanônù","Léopard","Aklassu","Coq"],"prescriptions":["Adorer Sakpata","Adorer Nà-Kinnessi","Faire annuellement Enna gni azon","Offrir de l’huile de palme et du kola"],"synthese":"Lètè-Mèdji associe courage, protection, ambition, connaissance de l’entourage et capacité à conserver ses biens à une forte passion, des conflits, des risques sentimentaux et des dangers cachés."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
