insert into public.fa_signs (slug, name) values ('tche-medji', 'Tchè-Mèdji') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 15, 'signe_mere', 15, '{"slug":"tche-medji","nom":"Tchè-Mèdji","ordre":15,"type":"signe_mere","position":"15e signe-mère","sexeSymbolique":"Masculin","maison":"Quinzième maison","divinites":"Sakpata, Kinnessi, Hêbiosso, Lissa, Gu, Tohossou","feuilles":"Nukunzawé, Hansimlin, Azéloko, Futukôdô","couleurs":"Aucune préférence particulière ; demande trois ensembles de couleurs, quelles qu’elles soient.","profil":["Tchè-Mèdji est présenté comme un signe très dangereux. Il est associé aux risques d’accident et de mort subite, à la guerre, à la révolution, à la réussite dépendant de l’habileté personnelle, au bonheur tardif et à la richesse suivie d’un risque de ruine par prodigalité.","Le porteur peut devenir un grand révolutionnaire, être prétentieux et aimer la guerre. Il souffre un peu mais peut obtenir le bonheur plus tard. Devenu riche, il risque de se ruiner par prodigalité.","Les sentiments dominent souvent son comportement : il peut être inconstant, ce qui ne favorise guère l’union. Le texte le décrit aussi comme misanthrope mais avec une conscience tranquille."],"devises":[{"ordre":1,"titre":"L’igname grillée dit à l’homme de se dépêcher","sens":"La réussite dépend de la prestance et de l’habileté ; sinon les bonnes occasions peuvent se perdre."},{"ordre":2,"titre":"Le vieux crâne et le jeune crâne","sens":"Le favi est menacé d’accident et de mort subite ; le corpus prescrit de conjurer ces risques par les sacrifices indiqués."},{"ordre":3,"titre":"Si tu me vois, tu vois la mort","sens":"Le favi a rencontré le distributeur du mal et de la mort et doit faire sans retard les adras prescrits."},{"ordre":4,"titre":"L’igname ne se casse pas lorsqu’on la déterre","sens":"Le favi a survécu à des dangers mortels ; le Fazun et les prescriptions sont associés à sa protection."}],"interdits":["Maïs grillé Agbadé mimê","Igname grillée Té mi mê","Pintade Sonù","Colas sauf le blanc","Perdrix Zùn sô / Assô","Tous les interdits de Sakpata","Haricot mélangé avec du maïs","Tout mélange de mets grillés","Porter des fagots de bois sur la tête","Toucher du bois partiellement consumé","Singes","Coq"],"prescriptions":["Adorer Sakpata","Adorer Nà","Adorer Hêbiosso","Faire E na gni azon, bo nà dio kù","Faire annuellement E na gni azon avec sacrifices et offrandes aux bokônons et féticheurs"],"synthese":"Tchè-Mèdji unit danger, lutte, révolution, richesse possible et bonheur tardif. La réussite dépend de l’habileté et de la capacité à saisir les occasions, tandis que les accidents et la mort subite constituent les grands avertissements."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
