insert into public.fa_signs (slug, name) values ('fu-medji', 'Fu-Mèdji') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 16, 'signe_mere', 16, '{"slug":"fu-medji","nom":"Fu-Mèdji","ordre":16,"type":"signe_mere","position":"16e et dernier signe-mère","sexeSymbolique":"Féminin","maison":"Seizième maison","divinites":"Odu, Lissa, Mawu, Nà, Hoho, Sakpata, Hêbiosso, Gu, Loko, Kpôvodun","feuilles":"Tutu, Kôgoto, Zêzêmà, Adantôfio, Sinfiffamà, Awiimà","couleurs":"Blanc principalement ; aucune autre couleur ne lui déplaît.","profil":["Fu-Mèdji clôt la série des seize signes-mères et est présenté comme la mère des quatorze autres signes géomanciques, Gbé étant le père selon la légende.","Le porteur peut avoir une forte autorité sur ses parents et occuper une haute place dans sa ville et sa famille. La vie peut être satisfaisante au début puis plus malheureuse à la fin.","La personne est rigoureuse donc parfois belliqueuse, intelligente, de bon cœur, franche, loyale et ambitieuse. Elle est très attachée à ses prérogatives, aux hiérarchies, à la discipline et à l’ordre. L’égoïsme peut nuire au bonheur sentimental. La longévité est probable à condition de se surveiller."],"devises":[{"ordre":1,"titre":"Les rivières se dessèchent, mais le repère du crocodile ne tarit jamais","sens":"Tout peut réussir au consultant ; il peut vivre longtemps mais doit se surveiller."},{"ordre":2,"titre":"Nul ne peut emporter le petit crocodile devant son père","sens":"Le consultant ne devrait pas connaître une mort tragique."},{"ordre":3,"titre":"Le savon disparaît tandis que la tête reste","sens":"Le favi est associé à la longévité."},{"ordre":4,"titre":"La calebasse se casse mais le récipient métallique résiste","sens":"Même sens : résistance et longévité."}],"interdits":["Dangbé / python sacré","Dan nù","Nà nù","Tê vê","Agbanlin","Crocodile Lo","Vanner le maïs","Éteindre une lampe en soufflant","Aviver le feu en soufflant selon certains devins","Pagnes rouges et objets rouges","Sorgho rouge Abôkun vôvô","Hyène","Léopard","Vin de palme","Afyanku","Coq","Porc","Chien"],"prescriptions":["Adorer Lissa","Adorer Mawu","Adorer Nà","Adorer Dù","Adorer Kpôvodun","Faire Hê nan - do nan gban / é na hênan","Faire annuellement de l’aumône aux piroguiers","Faire annuellement de l’aumône aux chauffeurs"],"synthese":"Fu-Mèdji est un signe de longévité, autorité, réussite, intelligence, ordre et résistance. Son défi majeur est de maîtriser rigidité, esprit belliqueux et égoïsme, surtout dans la vie sentimentale."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
