insert into public.fa_signs (slug, name) values ('tche-tula', 'Tchè-Tula') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 17, 'messager', null, '{"slug":"tche-tula","nom":"Tchè-Tula","ordre":null,"type":"messager","position":"Après les seize signes-mères","sexeSymbolique":"Non présenté comme signe-mère","maison":"Fonction transversale","divinites":"Loko, Hoho, Mawu, Lissa, Nà, Dji, Hêbiosso, Sakpata, Gu, Kpôvodù, Hu, Dàà, Aïzan","feuilles":"Accepte toutes les feuilles ; préfère Zuku-zwi et Adôdwê","couleurs":"Toutes les couleurs.","profil":["Tchè-Tula n’est pas un dix-septième signe-mère. Il est le Messager, récadère des seize signes-mères et des signes mineurs.","Il doit être nommé après les seize signes-mères et, dans son rôle de messager, avant et après les signes. Il accompagne les sacrifices Vonssissa et Adras destinés aux différents signes.","Il est présenté comme celui qui rend les sacrifices efficaces. Comme les signes en Tula, il possède des affinités avec Lègba. Sa fonction le met en relation avec de nombreux grands Vodù."],"devises":[{"ordre":1,"titre":"Celui qui transporte les bagages les conduit et les précède","sens":"Les bagages représentent les sacrifices de tous les signes ; cette devise décrit directement sa fonction."},{"ordre":2,"titre":"Si Klèbo prononce la prière de son père, sa bénédiction se réalisera","sens":"Les vœux et souhaits du consultant peuvent être exaucés."},{"ordre":3,"titre":"L’ordre verbal du souverain doit être exécuté","sens":"La parole d’autorité produit un effet ; le tonnerre impose le respect."},{"ordre":4,"titre":"La chauve-souris ne peut porter tous les malheurs de l’humanité","sens":"Tchè-Tula est présenté comme très fort et irremplaçable lorsqu’il porte les sacrifices de la vie."},{"ordre":5,"titre":"Sègbo Lissa prescrit et ses paroles se réalisent","sens":"Le consultant peut être naturellement respecté par son entourage et la société."}],"interdits":["Aucun interdit spécifique n’est donné dans cette fiche ; sa fonction porte surtout sur la transmission et l’accompagnement des sacrifices."],"prescriptions":["Nommer Tchè-Tula dans l’ordre rituel indiqué","L’associer aux Vonssissa et Adras","Accomplir les offrandes propitiatoires prescrites"],"synthese":"Tchè-Tula est le Messager : il accompagne, transporte et précède les sacrifices des signes. Sa fiche développe les thèmes de transmission, efficacité, force, parole d’autorité, exaucement et respect social."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
from public.fa_signs where slug = 'tche-tula'
