    source = excluded.source,
    status = excluded.status,
    updated_at = now();

insert into public.fa_signs (slug, name) values ('signe-017-gbe-yeku', 'GBE YEKU') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 18, 'signe_derive', null, '{"slug":"signe-017-gbe-yeku","nom":"GBE YEKU","ordre":null,"type":"signe_derive","position":"17e signe du catalogue ; premier des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Gbé ; premier signe dérivé de cette lignée","divinites":"Kluvito (défunts et ancêtres) et Hêviosso","feuilles":"Aucune feuille particulière n’est indiquée pour ce signe","couleurs":"Aucune couleur favorable n’est précisée ; le port de vêtements noirs est interdit.","profil":["GBE YEKU ouvre la série des 240 signes descendants issus des seize grands signes du Fâ. Il appartient à la maison de Gbé et occupe la première place parmi ses signes dérivés.","Le récit associé au signe parle de deux chasseurs. Le chien de l’un d’eux tombe dans un trou au cours d’une chasse. Son compagnon exige que l’animal soit tué et partagé malgré l’opposition de son propriétaire. Plus tard, un malheur comparable atteint la famille de celui qui avait imposé cette décision, le plaçant à son tour devant la dure règle qu’il avait fait subir à l’autre.","Le signe met ainsi en garde contre la rivalité, la colère, l’injustice et la vengeance. Le porteur doit réfléchir aux conséquences de ses actes, éviter de profiter de la faiblesse d’autrui et rechercher une conduite équitable dans les conflits.","Le respect des obligations envers Kluvito et Hêviosso est présenté comme une voie d’apaisement et de protection. Il est associé à la recherche d’une vie stable, de la paix, de la prospérité, des bienfaits et de la longévité."],"devises":[{"ordre":1,"titre":"Le chasseur des morts et le chasseur des vivants entrent en rivalité","sens":"Une opposition mal maîtrisée peut conduire à une décision injuste. Le porteur est invité à privilégier l’équité plutôt que le rapport de force."},{"ordre":2,"titre":"Le chien tombé dans le trou est tué et partagé","sens":"Le malheur d’un proche ne doit pas devenir une occasion de profit. Toute décision imposée sans compassion peut entraîner des conséquences durables."},{"ordre":3,"titre":"L’épreuve revient dans la maison de celui qui avait imposé le partage","sens":"Chacun peut un jour être soumis à la règle qu’il applique aux autres. Le signe demande de mesurer la portée de ses actes avant de les imposer."},{"ordre":4,"titre":"Celui qui fait du mal rencontre le mal sur son chemin","sens":"La conduite envers autrui finit par produire un retour. La sagesse consiste à assumer ses responsabilités et à interrompre le cycle de la vengeance."}],"interdits":["Aller à la chasse","Porter des vêtements noirs","Manger de l’igname frite"],"prescriptions":["Prendre soin de Kluvito et respecter les obligations liées aux défunts et aux ancêtres","Prendre soin de Hêviosso","Accomplir les prescriptions indiquées afin de rechercher paix, prospérité, bienfaits et longévité"],"synthese":"GBE YEKU est un signe de responsabilité, d’équité et de maîtrise de soi. Son récit enseigne que le tort causé à autrui peut revenir vers son auteur. Le porteur doit éviter la chasse, les vêtements noirs et l’igname frite, tout en respectant les obligations liées à Kluvito et Hêviosso afin de rechercher paix, prospérité et longévité."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
from public.fa_signs where slug = 'signe-017-gbe-yeku'
