insert into public.fa_signs (slug, name) values ('signe-019-gbe-di', 'GBE DI') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 20, 'signe_derive', null, '{"slug":"signe-019-gbe-di","nom":"GBE DI","ordre":null,"type":"signe_derive","position":"19e signe du catalogue ; 3e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Gbè ; signe dérivé de cette lignée","divinites":"Dan, Hêviosso, Tohossou","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["GBE DI appartient à la maison de Gbè. Il occupe la 3e place parmi les 240 signes descendants.","Les images centrales du récit sont le tambour et le pagne. Le signe place la préservation de la vie au premier plan et demande de reconnaître le danger avant qu''il ne devienne irréversible. La prospérité est possible, mais sa durée dépend d''une gestion honnête des biens et du respect des engagements pris. La parole possède ici un pouvoir particulier : une confidence révélée, une promesse rompue ou un propos irréfléchi peut bouleverser une destinée.","L''eau marque une transformation : ce qui apporte la vie peut aussi surprendre une personne insuffisamment préparée. L''accomplissement des obligations indiquées est associé à l''apaisement, à la protection et au rétablissement de l''équilibre.","Son enseignement articule danger, prospérité, parole et eau. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La vigilance protège la vie","sens":"Le danger perd une part de sa force lorsqu''il est reconnu tôt et traité avec calme."},{"ordre":2,"titre":"La richesse demande une conduite juste","sens":"L''abondance demeure favorable lorsqu''elle circule sans orgueil, tromperie ni abus de pouvoir."},{"ordre":3,"titre":"La parole mesurée préserve","sens":"Le silence et la discrétion protègent ce qui doit mûrir avant d''être rendu public."},{"ordre":4,"titre":"L''eau transforme ce qu''elle touche","sens":"Toute force bénéfique demande une juste préparation afin que son passage nourrisse au lieu de désorganiser."},{"ordre":5,"titre":"L''obligation accomplie rétablit l''équilibre","sens":"Le signe relie le mieux-être à une action concrète, menée avec sérieux et continuité."}],"interdits":["Consommer de l''huile rouge","Boire du sodabi","Prêter de l''argent"],"prescriptions":["Honorer Dan et respecter les obligations qui lui sont liées","Honorer Hêviosso et respecter les obligations qui lui sont liées","Honorer Tohossou et respecter les obligations qui lui sont liées","Garder les confidences et mesurer toute parole donnée"],"synthese":"GBE DI réunit des enseignements liés à danger, prospérité, parole et eau. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
