insert into public.fa_signs (slug, name) values ('signe-020-gbe-loso', 'GBE LOSO') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 21, 'signe_derive', null, '{"slug":"signe-020-gbe-loso","nom":"GBE LOSO","ordre":null,"type":"signe_derive","position":"20e signe du catalogue ; 4e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Gbè ; signe dérivé de cette lignée","divinites":"Hêviosso","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Le port de vêtements rouge est déconseillé.","profil":["GBE LOSO appartient à la maison de Gbè. Il occupe la 4e place parmi les 240 signes descendants.","Les protagonistes nommés sont Lonfin. Les images centrales du récit sont la terre, la mer, la maison et le maïs. Son déroulement met en jeu une tension familiale qui révèle les devoirs de chacun puis une question d''autorité, de succession ou de gouvernement. Une fonction d''autorité peut se présenter. Elle doit servir la communauté et s''exercer sans précipitation ni domination. La vie familiale constitue un lieu d''épreuve et d''accomplissement ; le dialogue, la fidélité et le respect des proches y sont déterminants. L''eau marque une transformation : ce qui apporte la vie peut aussi surprendre une personne insuffisamment préparée.","L''accomplissement des obligations indiquées est associé à l''apaisement, à la protection et au rétablissement de l''équilibre.","Son enseignement articule autorité, famille, eau et obligations. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"Le commandement se prouve par l''équité","sens":"Diriger engage la responsabilité du porteur envers ceux qui dépendent de ses décisions."},{"ordre":2,"titre":"La paix du foyer se construit","sens":"Les liens familiaux se consolident par la patience, la parole tenue et la protection réciproque."},{"ordre":3,"titre":"L''eau transforme ce qu''elle touche","sens":"Toute force bénéfique demande une juste préparation afin que son passage nourrisse au lieu de désorganiser."},{"ordre":4,"titre":"L''obligation accomplie rétablit l''équilibre","sens":"Le signe relie le mieux-être à une action concrète, menée avec sérieux et continuité."}],"interdits":["Consommer de l''huile rouge","Porter des vêtements rouges","Épouser une personne au teint clair"],"prescriptions":["Honorer Hêviosso et respecter les obligations qui lui sont liées","Préserver le dialogue familial et prendre soin des parents et des aînés"],"synthese":"GBE LOSO réunit des enseignements liés à autorité, famille, eau et obligations. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
