insert into public.fa_signs (slug, name) values ('signe-021-gbe-winlin', 'GBE WINLIN') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 22, 'signe_derive', null, '{"slug":"signe-021-gbe-winlin","nom":"GBE WINLIN","ordre":null,"type":"signe_derive","position":"21e signe du catalogue ; 5e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Gbè ; signe dérivé de cette lignée","divinites":"Tohossou","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["GBE WINLIN appartient à la maison de Gbè. Il occupe la 5e place parmi les 240 signes descendants.","Les protagonistes nommés sont Amion, Soun, Hoba et Dagbe. Le signe place la préservation de la vie au premier plan et demande de reconnaître le danger avant qu''il ne devienne irréversible. Le signe rappelle les devoirs envers les parents et les aînés, dont l''expérience peut prévenir des décisions lourdes de conséquences. La colère rapide est présentée comme une faiblesse dangereuse. Le porteur gagne à différer sa réaction et à retrouver son jugement.","La maternité et la naissance appellent une protection particulière, ainsi que le respect strict des recommandations reçues. Les relations d''amitié sont mises à l''épreuve. Le porteur doit distinguer la solidarité véritable d''une proximité intéressée.","Son enseignement articule danger, aînés, colère et maternité. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La vigilance protège la vie","sens":"Le danger perd une part de sa force lorsqu''il est reconnu tôt et traité avec calme."},{"ordre":2,"titre":"La parole des aînés éclaire le chemin","sens":"Écouter ceux qui précèdent permet de reconnaître un danger déjà rencontré par la communauté."},{"ordre":3,"titre":"La colère ne doit pas décider","sens":"Prendre le temps de se calmer évite qu''une offense passagère produise un dommage durable."},{"ordre":4,"titre":"La naissance se protège avec attention","sens":"La vie en formation demande prudence, accompagnement et accomplissement des obligations indiquées."},{"ordre":5,"titre":"L''amitié se reconnaît dans l''épreuve","sens":"Un compagnon loyal protège et conseille ; une relation fondée sur l''intérêt se révèle lorsque survient le danger."}],"interdits":["Manger du maïs","Provoquer un avortement","Céder à la colère","Errer seul pendant la nuit profonde"],"prescriptions":["Accomplir avec sérieux les sacrifices et offrandes prescrits","Honorer Tohossou et respecter les obligations qui lui sont liées","Préserver le dialogue familial et prendre soin des parents et des aînés","Différer les décisions prises sous l''effet de la colère et rechercher l''apaisement","Prendre au sérieux les avertissements concernant la santé et la protection de la vie"],"synthese":"GBE WINLIN réunit des enseignements liés à danger, aînés, colère et maternité. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
