insert into public.fa_signs (slug, name) values ('signe-022-gbe-abla', 'GBE ABLA') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 23, 'signe_derive', null, '{"slug":"signe-022-gbe-abla","nom":"GBE ABLA","ordre":null,"type":"signe_derive","position":"22e signe du catalogue ; 6e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Gbè ; signe dérivé de cette lignée","divinites":"Dan, Hêviosso","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["GBE ABLA appartient à la maison de Gbè. Il occupe la 6e place parmi les 240 signes descendants.","Les protagonistes nommés sont Gbagbada et Heviosso. Les images centrales du récit sont la feuille, la terre, le feu et le maïs. La prospérité est possible, mais sa durée dépend d''une gestion honnête des biens et du respect des engagements pris. La vie familiale constitue un lieu d''épreuve et d''accomplissement ; le dialogue, la fidélité et le respect des proches y sont déterminants. La parole possède ici un pouvoir particulier : une confidence révélée, une promesse rompue ou un propos irréfléchi peut bouleverser une destinée.","L''intégrité constitue une protection essentielle. Le gain obtenu par le mensonge ou l''appropriation du bien d''autrui finit par fragiliser son auteur. L''accomplissement des obligations indiquées est associé à l''apaisement, à la protection et au rétablissement de l''équilibre.","Son enseignement articule prospérité, famille, parole et intégrité. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La richesse demande une conduite juste","sens":"L''abondance demeure favorable lorsqu''elle circule sans orgueil, tromperie ni abus de pouvoir."},{"ordre":2,"titre":"La paix du foyer se construit","sens":"Les liens familiaux se consolident par la patience, la parole tenue et la protection réciproque."},{"ordre":3,"titre":"La parole mesurée préserve","sens":"Le silence et la discrétion protègent ce qui doit mûrir avant d''être rendu public."},{"ordre":4,"titre":"Le bien d''autrui ne fonde aucune réussite","sens":"La prospérité durable se construit par l''honnêteté et le respect des droits de chacun."},{"ordre":5,"titre":"L''obligation accomplie rétablit l''équilibre","sens":"Le signe relie le mieux-être à une action concrète, menée avec sérieux et continuité."}],"interdits":["Consommer de l''huile rouge","Manger de l''akassa","Manger du serpent"],"prescriptions":["Honorer Dan et respecter les obligations qui lui sont liées","Honorer Hêviosso et respecter les obligations qui lui sont liées","Préserver le dialogue familial et prendre soin des parents et des aînés","Garder les confidences et mesurer toute parole donnée"],"synthese":"GBE ABLA réunit des enseignements liés à prospérité, famille, parole et intégrité. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
