insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 25, 'signe_derive', null, '{"slug":"signe-024-gbe-guda","nom":"GBE GUDA","ordre":null,"type":"signe_derive","position":"24e signe du catalogue ; 8e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Gbè ; signe dérivé de cette lignée","divinites":"Tohossou","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["GBE GUDA appartient à la maison de Gbè. Il occupe la 8e place parmi les 240 signes descendants.","Les images centrales du récit sont le trône. Son déroulement met en jeu une épreuve où la vie et la mort sont mises en balance puis une question d''autorité, de succession ou de gouvernement. Le signe place la préservation de la vie au premier plan et demande de reconnaître le danger avant qu''il ne devienne irréversible. Une confiance mal placée peut exposer le porteur à la ruse ou à la trahison ; il lui faut observer les actes autant que les paroles. La prospérité est possible, mais sa durée dépend d''une gestion honnête des biens et du respect des engagements pris.","Une fonction d''autorité peut se présenter. Elle doit servir la communauté et s''exercer sans précipitation ni domination. La vie familiale constitue un lieu d''épreuve et d''accomplissement ; le dialogue, la fidélité et le respect des proches y sont déterminants.","Son enseignement articule danger, trahison, prospérité et autorité. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La vigilance protège la vie","sens":"Le danger perd une part de sa force lorsqu''il est reconnu tôt et traité avec calme."},{"ordre":2,"titre":"La confiance se donne avec discernement","sens":"La loyauté se vérifie dans les actes. Le signe invite à rester ouvert sans ignorer les indices d''une intention cachée."},{"ordre":3,"titre":"La richesse demande une conduite juste","sens":"L''abondance demeure favorable lorsqu''elle circule sans orgueil, tromperie ni abus de pouvoir."},{"ordre":4,"titre":"Le commandement se prouve par l''équité","sens":"Diriger engage la responsabilité du porteur envers ceux qui dépendent de ses décisions."},{"ordre":5,"titre":"La paix du foyer se construit","sens":"Les liens familiaux se consolident par la patience, la parole tenue et la protection réciproque."}],"interdits":["Manger de la tourterelle","S''établir durablement à l''étranger"],"prescriptions":["Accomplir avec sérieux les sacrifices et offrandes prescrits","Honorer Tohossou et respecter les obligations qui lui sont liées","Préserver le dialogue familial et prendre soin des parents et des aînés"],"synthese":"GBE GUDA réunit des enseignements liés à danger, trahison, prospérité et autorité. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
