insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 26, 'signe_derive', null, '{"slug":"signe-025-gbe-sa","nom":"GBE SA","ordre":null,"type":"signe_derive","position":"25e signe du catalogue ; 9e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Gbè ; signe dérivé de cette lignée","divinites":"Dan, Hêviosso, Minonnan","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["GBE SA appartient à la maison de Gbè. Il occupe la 9e place parmi les 240 signes descendants.","Les protagonistes nommés sont Gris-Gris, Aïzan et Demontchi. Les images centrales du récit sont le bélier, la pluie, la maison et le chemin. Son déroulement met en jeu l''accomplissement d''une obligation rituelle, une consultation destinée à éclairer une décision puis une épreuve où la vie et la mort sont mises en balance. Le signe place la préservation de la vie au premier plan et demande de reconnaître le danger avant qu''il ne devienne irréversible. La prospérité est possible, mais sa durée dépend d''une gestion honnête des biens et du respect des engagements pris. Une fonction d''autorité peut se présenter. Elle doit servir la communauté et s''exercer sans précipitation ni domination.","La vie familiale constitue un lieu d''épreuve et d''accomplissement ; le dialogue, la fidélité et le respect des proches y sont déterminants. La colère rapide est présentée comme une faiblesse dangereuse. Le porteur gagne à différer sa réaction et à retrouver son jugement.","Son enseignement articule danger, prospérité, autorité et famille. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La vigilance protège la vie","sens":"Le danger perd une part de sa force lorsqu''il est reconnu tôt et traité avec calme."},{"ordre":2,"titre":"La richesse demande une conduite juste","sens":"L''abondance demeure favorable lorsqu''elle circule sans orgueil, tromperie ni abus de pouvoir."},{"ordre":3,"titre":"Le commandement se prouve par l''équité","sens":"Diriger engage la responsabilité du porteur envers ceux qui dépendent de ses décisions."},{"ordre":4,"titre":"La paix du foyer se construit","sens":"Les liens familiaux se consolident par la patience, la parole tenue et la protection réciproque."},{"ordre":5,"titre":"La colère ne doit pas décider","sens":"Prendre le temps de se calmer évite qu''une offense passagère produise un dommage durable."}],"interdits":["Manger du gombo","Manger de la gazelle","Manger avec précipitation en public"],"prescriptions":["Accomplir avec sérieux les sacrifices et offrandes prescrits","Honorer Dan et respecter les obligations qui lui sont liées","Honorer Hêviosso et respecter les obligations qui lui sont liées","Honorer Minonnan et respecter les obligations qui lui sont liées","Préserver le dialogue familial et prendre soin des parents et des aînés","Différer les décisions prises sous l''effet de la colère et rechercher l''apaisement"],"synthese":"GBE SA réunit des enseignements liés à danger, prospérité, autorité et famille. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
