insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 27, 'signe_derive', null, '{"slug":"signe-026-gbe-trukpin","nom":"GBE TRUKPIN","ordre":null,"type":"signe_derive","position":"26e signe du catalogue ; 10e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Gbè ; signe dérivé de cette lignée","divinites":"Aucune divinité particulière n''est indiquée pour ce signe","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Le port de vêtements rouge est déconseillé.","profil":["GBE TRUKPIN appartient à la maison de Gbè. Il occupe la 10e place parmi les 240 signes descendants.","Les protagonistes nommés sont Hoviosso, Fayidekouin, Heviosso et Sossou. Les images centrales du récit sont l''argent. Son déroulement met en jeu l''accomplissement d''une obligation rituelle, un déplacement qui oblige à choisir sa direction avec soin puis une recherche de prospérité qui éprouve l''intégrité. La prospérité est possible, mais sa durée dépend d''une gestion honnête des biens et du respect des engagements pris. La vie familiale constitue un lieu d''épreuve et d''accomplissement ; le dialogue, la fidélité et le respect des proches y sont déterminants. Les déplacements exigent préparation et prudence. Un changement de lieu peut ouvrir une possibilité tout en exposant à l''isolement.","L''eau marque une transformation : ce qui apporte la vie peut aussi surprendre une personne insuffisamment préparée. Les relations d''amitié sont mises à l''épreuve. Le porteur doit distinguer la solidarité véritable d''une proximité intéressée.","Son enseignement articule prospérité, famille, déplacement et eau. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La richesse demande une conduite juste","sens":"L''abondance demeure favorable lorsqu''elle circule sans orgueil, tromperie ni abus de pouvoir."},{"ordre":2,"titre":"La paix du foyer se construit","sens":"Les liens familiaux se consolident par la patience, la parole tenue et la protection réciproque."},{"ordre":3,"titre":"Le voyage commence par la préparation","sens":"Changer de lieu devient favorable lorsque les obligations sont accomplies et que la route est choisie avec discernement."},{"ordre":4,"titre":"L''eau transforme ce qu''elle touche","sens":"Toute force bénéfique demande une juste préparation afin que son passage nourrisse au lieu de désorganiser."},{"ordre":5,"titre":"L''amitié se reconnaît dans l''épreuve","sens":"Un compagnon loyal protège et conseille ; une relation fondée sur l''intérêt se révèle lorsque survient le danger."}],"interdits":["Manger du haricot","Manger du maïs","Porter des vêtements rouges"],"prescriptions":["Accomplir avec sérieux les sacrifices et offrandes prescrits","Préserver le dialogue familial et prendre soin des parents et des aînés"],"synthese":"GBE TRUKPIN réunit des enseignements liés à prospérité, famille, déplacement et eau. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
