insert into public.fa_signs (slug, name) values ('signe-027-gbe-tula', 'GBE TULA') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 28, 'signe_derive', null, '{"slug":"signe-027-gbe-tula","nom":"GBE TULA","ordre":null,"type":"signe_derive","position":"27e signe du catalogue ; 11e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Gbè ; signe dérivé de cette lignée","divinites":"Dan, Hêviosso, Tohossou","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["GBE TULA appartient à la maison de Gbè. Il occupe la 11e place parmi les 240 signes descendants.","Les protagonistes nommés sont Zinsou et Sagbo. Les images centrales du récit sont la terre et le chemin. Son déroulement met en jeu un déplacement qui oblige à choisir sa direction avec soin, une recherche de prospérité qui éprouve l''intégrité puis une fragilité qui demande protection et soin. Les rivalités annoncées doivent être contenues par la mesure, car une victoire obtenue dans la colère peut détruire l''équilibre du groupe. La prospérité est possible, mais sa durée dépend d''une gestion honnête des biens et du respect des engagements pris. Les déplacements exigent préparation et prudence. Un changement de lieu peut ouvrir une possibilité tout en exposant à l''isolement.","L''eau marque une transformation : ce qui apporte la vie peut aussi surprendre une personne insuffisamment préparée. La santé demande une attention précoce. Le signe déconseille de minimiser les symptômes ou de retarder les soins nécessaires.","Son enseignement articule conflit, prospérité, déplacement et eau. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"Deux forces opposées doivent retrouver la mesure","sens":"Le conflit devient fécond lorsque chacun renonce à l''escalade et recherche une solution juste."},{"ordre":2,"titre":"La richesse demande une conduite juste","sens":"L''abondance demeure favorable lorsqu''elle circule sans orgueil, tromperie ni abus de pouvoir."},{"ordre":3,"titre":"Le voyage commence par la préparation","sens":"Changer de lieu devient favorable lorsque les obligations sont accomplies et que la route est choisie avec discernement."},{"ordre":4,"titre":"L''eau transforme ce qu''elle touche","sens":"Toute force bénéfique demande une juste préparation afin que son passage nourrisse au lieu de désorganiser."},{"ordre":5,"titre":"Le corps avertit avant de céder","sens":"Écouter les premiers signes de faiblesse permet d''agir avant que l''épreuve ne s''aggrave."}],"interdits":["Écarter les comportements imprudents signalés par le signe"],"prescriptions":["Honorer Dan et respecter les obligations qui lui sont liées","Honorer Hêviosso et respecter les obligations qui lui sont liées","Honorer Tohossou et respecter les obligations qui lui sont liées","Différer les décisions prises sous l''effet de la colère et rechercher l''apaisement","Prendre au sérieux les avertissements concernant la santé et la protection de la vie"],"synthese":"GBE TULA réunit des enseignements liés à conflit, prospérité, déplacement et eau. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
