select id, 29, 'signe_derive', null, '{"slug":"signe-028-gbe-lete","nom":"GBE LETE","ordre":null,"type":"signe_derive","position":"28e signe du catalogue ; 12e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Gbè ; signe dérivé de cette lignée","divinites":"Hêviosso, Sakpata","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Le port de vêtements noir est déconseillé.","profil":["GBE LETE appartient à la maison de Gbè. Il occupe la 12e place parmi les 240 signes descendants.","L''enseignement part d''une situation ordinaire et en révèle les conséquences morales et spirituelles. La prospérité est possible, mais sa durée dépend d''une gestion honnête des biens et du respect des engagements pris. L''eau marque une transformation : ce qui apporte la vie peut aussi surprendre une personne insuffisamment préparée. Le signe appelle à se protéger des influences hostiles sans nourrir la peur ni répondre à l''agression par l''imprudence.","L''accomplissement des obligations indiquées est associé à l''apaisement, à la protection et au rétablissement de l''équilibre.","Son enseignement articule prospérité, eau, forces hostiles et obligations. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La richesse demande une conduite juste","sens":"L''abondance demeure favorable lorsqu''elle circule sans orgueil, tromperie ni abus de pouvoir."},{"ordre":2,"titre":"L''eau transforme ce qu''elle touche","sens":"Toute force bénéfique demande une juste préparation afin que son passage nourrisse au lieu de désorganiser."},{"ordre":3,"titre":"La protection exige lucidité","sens":"La prudence, la discrétion et le respect des obligations forment une défense plus sûre que la provocation."},{"ordre":4,"titre":"L''obligation accomplie rétablit l''équilibre","sens":"Le signe relie le mieux-être à une action concrète, menée avec sérieux et continuité."}],"interdits":["Porter des vêtements noirs"],"prescriptions":["Accomplir avec sérieux les sacrifices et offrandes prescrits","Honorer Hêviosso et respecter les obligations qui lui sont liées","Honorer Sakpata et respecter les obligations qui lui sont liées"],"synthese":"GBE LETE réunit des enseignements liés à prospérité, eau, forces hostiles et obligations. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
