insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 30, 'signe_derive', null, '{"slug":"signe-029-gbe-ka","nom":"GBE KA","ordre":null,"type":"signe_derive","position":"29e signe du catalogue ; 13e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Gbè ; signe dérivé de cette lignée","divinites":"Hoho, Lègba, Sakpata, Tohossou","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["GBE KA appartient à la maison de Gbè. Il occupe la 13e place parmi les 240 signes descendants.","Les protagonistes nommés sont Gan, Fayidekouin, Sakpata et Kou. Les images centrales du récit sont le vent, la maison et le maïs. Son déroulement met en jeu l''accomplissement d''une obligation rituelle, une consultation destinée à éclairer une décision puis une épreuve où la vie et la mort sont mises en balance. Le signe place la préservation de la vie au premier plan et demande de reconnaître le danger avant qu''il ne devienne irréversible. Une confiance mal placée peut exposer le porteur à la ruse ou à la trahison ; il lui faut observer les actes autant que les paroles. Les rivalités annoncées doivent être contenues par la mesure, car une victoire obtenue dans la colère peut détruire l''équilibre du groupe.","La prospérité est possible, mais sa durée dépend d''une gestion honnête des biens et du respect des engagements pris. Une fonction d''autorité peut se présenter. Elle doit servir la communauté et s''exercer sans précipitation ni domination.","Son enseignement articule danger, trahison, conflit et prospérité. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La vigilance protège la vie","sens":"Le danger perd une part de sa force lorsqu''il est reconnu tôt et traité avec calme."},{"ordre":2,"titre":"La confiance se donne avec discernement","sens":"La loyauté se vérifie dans les actes. Le signe invite à rester ouvert sans ignorer les indices d''une intention cachée."},{"ordre":3,"titre":"Deux forces opposées doivent retrouver la mesure","sens":"Le conflit devient fécond lorsque chacun renonce à l''escalade et recherche une solution juste."},{"ordre":4,"titre":"La richesse demande une conduite juste","sens":"L''abondance demeure favorable lorsqu''elle circule sans orgueil, tromperie ni abus de pouvoir."},{"ordre":5,"titre":"Le commandement se prouve par l''équité","sens":"Diriger engage la responsabilité du porteur envers ceux qui dépendent de ses décisions."}],"interdits":["Épouser une personne au teint clair"],"prescriptions":["Accomplir avec sérieux les sacrifices et offrandes prescrits","Honorer Hoho et respecter les obligations qui lui sont liées","Honorer Lègba et respecter les obligations qui lui sont liées","Honorer Sakpata et respecter les obligations qui lui sont liées","Honorer Tohossou et respecter les obligations qui lui sont liées","Préserver le dialogue familial et prendre soin des parents et des aînés"],"synthese":"GBE KA réunit des enseignements liés à danger, trahison, conflit et prospérité. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
