select id, 31, 'signe_derive', null, '{"slug":"signe-030-gbe-tche","nom":"GBE TCHE","ordre":null,"type":"signe_derive","position":"30e signe du catalogue ; 14e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Gbè ; signe dérivé de cette lignée","divinites":"Lègba, Tohossou","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Le port de vêtements rouge est déconseillé.","profil":["GBE TCHE appartient à la maison de Gbè. Il occupe la 14e place parmi les 240 signes descendants.","Les protagonistes nommés sont Dokoun, Gbo, Zoun et Min. Les images centrales du récit sont la mer, le tambour, la houe et le maïs. Son déroulement met en jeu une épreuve où la vie et la mort sont mises en balance, une tension familiale qui révèle les devoirs de chacun puis une recherche de prospérité qui éprouve l''intégrité. Le signe place la préservation de la vie au premier plan et demande de reconnaître le danger avant qu''il ne devienne irréversible. La prospérité est possible, mais sa durée dépend d''une gestion honnête des biens et du respect des engagements pris. La vie familiale constitue un lieu d''épreuve et d''accomplissement ; le dialogue, la fidélité et le respect des proches y sont déterminants.","La parole possède ici un pouvoir particulier : une confidence révélée, une promesse rompue ou un propos irréfléchi peut bouleverser une destinée. L''eau marque une transformation : ce qui apporte la vie peut aussi surprendre une personne insuffisamment préparée.","Son enseignement articule danger, prospérité, famille et parole. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La vigilance protège la vie","sens":"Le danger perd une part de sa force lorsqu''il est reconnu tôt et traité avec calme."},{"ordre":2,"titre":"La richesse demande une conduite juste","sens":"L''abondance demeure favorable lorsqu''elle circule sans orgueil, tromperie ni abus de pouvoir."},{"ordre":3,"titre":"La paix du foyer se construit","sens":"Les liens familiaux se consolident par la patience, la parole tenue et la protection réciproque."},{"ordre":4,"titre":"La parole mesurée préserve","sens":"Le silence et la discrétion protègent ce qui doit mûrir avant d''être rendu public."},{"ordre":5,"titre":"L''eau transforme ce qu''elle touche","sens":"Toute force bénéfique demande une juste préparation afin que son passage nourrisse au lieu de désorganiser."}],"interdits":["Boire du sodabi","Porter des vêtements rouges"],"prescriptions":["Honorer Lègba et respecter les obligations qui lui sont liées","Honorer Tohossou et respecter les obligations qui lui sont liées","Préserver le dialogue familial et prendre soin des parents et des aînés","Garder les confidences et mesurer toute parole donnée"],"synthese":"GBE TCHE réunit des enseignements liés à danger, prospérité, famille et parole. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
