insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 37, 'signe_derive', null, '{"slug":"signe-036-yeku-do-winlin","nom":"YEKU DO WINLIN","ordre":null,"type":"signe_derive","position":"36e signe du catalogue ; 20e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Yèku ; signe dérivé de cette lignée","divinites":"Dan, Tohossou","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["YEKU DO WINLIN appartient à la maison de Yèku. Il occupe la 20e place parmi les 240 signes descendants.","L''enseignement part d''une situation ordinaire et en révèle les conséquences morales et spirituelles. Le signe place la préservation de la vie au premier plan et demande de reconnaître le danger avant qu''il ne devienne irréversible. L''eau marque une transformation : ce qui apporte la vie peut aussi surprendre une personne insuffisamment préparée. L''intégrité constitue une protection essentielle. Le gain obtenu par le mensonge ou l''appropriation du bien d''autrui finit par fragiliser son auteur.","L''accomplissement des obligations indiquées est associé à l''apaisement, à la protection et au rétablissement de l''équilibre.","Son enseignement articule danger, eau, intégrité et obligations. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La vigilance protège la vie","sens":"Le danger perd une part de sa force lorsqu''il est reconnu tôt et traité avec calme."},{"ordre":2,"titre":"L''eau transforme ce qu''elle touche","sens":"Toute force bénéfique demande une juste préparation afin que son passage nourrisse au lieu de désorganiser."},{"ordre":3,"titre":"Le bien d''autrui ne fonde aucune réussite","sens":"La prospérité durable se construit par l''honnêteté et le respect des droits de chacun."},{"ordre":4,"titre":"L''obligation accomplie rétablit l''équilibre","sens":"Le signe relie le mieux-être à une action concrète, menée avec sérieux et continuité."}],"interdits":["Manger du serpent"],"prescriptions":["Honorer Dan et respecter les obligations qui lui sont liées","Honorer Tohossou et respecter les obligations qui lui sont liées"],"synthese":"YEKU DO WINLIN réunit des enseignements liés à danger, eau, intégrité et obligations. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
