insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 39, 'signe_derive', null, '{"slug":"signe-038-yeku-da-aklan","nom":"YEKU DA AKLAN","ordre":null,"type":"signe_derive","position":"38e signe du catalogue ; 22e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Yèku ; signe dérivé de cette lignée","divinites":"Sakpata","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Le port de vêtements rouge est déconseillé.","profil":["YEKU DA AKLAN appartient à la maison de Yèku. Il occupe la 22e place parmi les 240 signes descendants.","Les protagonistes nommés sont Yédjèkanmè, Lodo et Hinnouho. Son déroulement met en jeu une question d''autorité, de succession ou de gouvernement. La prospérité est possible, mais sa durée dépend d''une gestion honnête des biens et du respect des engagements pris. Une fonction d''autorité peut se présenter. Elle doit servir la communauté et s''exercer sans précipitation ni domination. La vie familiale constitue un lieu d''épreuve et d''accomplissement ; le dialogue, la fidélité et le respect des proches y sont déterminants.","Le signe rappelle les devoirs envers les parents et les aînés, dont l''expérience peut prévenir des décisions lourdes de conséquences. L''accomplissement des obligations indiquées est associé à l''apaisement, à la protection et au rétablissement de l''équilibre.","Son enseignement articule prospérité, autorité, famille et aînés. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La richesse demande une conduite juste","sens":"L''abondance demeure favorable lorsqu''elle circule sans orgueil, tromperie ni abus de pouvoir."},{"ordre":2,"titre":"Le commandement se prouve par l''équité","sens":"Diriger engage la responsabilité du porteur envers ceux qui dépendent de ses décisions."},{"ordre":3,"titre":"La paix du foyer se construit","sens":"Les liens familiaux se consolident par la patience, la parole tenue et la protection réciproque."},{"ordre":4,"titre":"La parole des aînés éclaire le chemin","sens":"Écouter ceux qui précèdent permet de reconnaître un danger déjà rencontré par la communauté."},{"ordre":5,"titre":"L''obligation accomplie rétablit l''équilibre","sens":"Le signe relie le mieux-être à une action concrète, menée avec sérieux et continuité."}],"interdits":["Manger du maïs","Porter des vêtements rouges"],"prescriptions":["Honorer Sakpata et respecter les obligations qui lui sont liées","Préserver le dialogue familial et prendre soin des parents et des aînés"],"synthese":"YEKU DA AKLAN réunit des enseignements liés à prospérité, autorité, famille et aînés. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
