insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 45, 'signe_derive', null, '{"slug":"signe-044-yeku-si-ka","nom":"YEKU SI KA","ordre":null,"type":"signe_derive","position":"44e signe du catalogue ; 28e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Yèku ; signe dérivé de cette lignée","divinites":"Aucune divinité particulière n''est indiquée pour ce signe","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["YEKU SI KA appartient à la maison de Yèku. Il occupe la 28e place parmi les 240 signes descendants.","Les protagonistes nommés sont Non, Nou, Yekou et Adjahossou. Les images centrales du récit sont la calebasse, la houe et le maïs. Son déroulement met en jeu une épreuve où la vie et la mort sont mises en balance, une tension familiale qui révèle les devoirs de chacun puis une recherche de prospérité qui éprouve l''intégrité. Le signe place la préservation de la vie au premier plan et demande de reconnaître le danger avant qu''il ne devienne irréversible. La prospérité est possible, mais sa durée dépend d''une gestion honnête des biens et du respect des engagements pris. La vie familiale constitue un lieu d''épreuve et d''accomplissement ; le dialogue, la fidélité et le respect des proches y sont déterminants.","L''eau marque une transformation : ce qui apporte la vie peut aussi surprendre une personne insuffisamment préparée. L''accomplissement des obligations indiquées est associé à l''apaisement, à la protection et au rétablissement de l''équilibre.","Son enseignement articule danger, prospérité, famille et eau. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La vigilance protège la vie","sens":"Le danger perd une part de sa force lorsqu''il est reconnu tôt et traité avec calme."},{"ordre":2,"titre":"La richesse demande une conduite juste","sens":"L''abondance demeure favorable lorsqu''elle circule sans orgueil, tromperie ni abus de pouvoir."},{"ordre":3,"titre":"La paix du foyer se construit","sens":"Les liens familiaux se consolident par la patience, la parole tenue et la protection réciproque."},{"ordre":4,"titre":"L''eau transforme ce qu''elle touche","sens":"Toute force bénéfique demande une juste préparation afin que son passage nourrisse au lieu de désorganiser."},{"ordre":5,"titre":"L''obligation accomplie rétablit l''équilibre","sens":"Le signe relie le mieux-être à une action concrète, menée avec sérieux et continuité."}],"interdits":["Écarter les comportements imprudents signalés par le signe"],"prescriptions":["Préserver le dialogue familial et prendre soin des parents et des aînés"],"synthese":"YEKU SI KA réunit des enseignements liés à danger, prospérité, famille et eau. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
