insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 47, 'signe_derive', null, '{"slug":"signe-046-yeku-ti-fu","nom":"YEKU TI FU","ordre":null,"type":"signe_derive","position":"46e signe du catalogue ; 30e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Yèku ; signe dérivé de cette lignée","divinites":"Sakpata, Tohossou","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["YEKU TI FU appartient à la maison de Yèku. Il occupe la 30e place parmi les 240 signes descendants.","Son déroulement met en jeu une épreuve où la vie et la mort sont mises en balance, une opposition dont l''issue dépend de la maîtrise de soi puis une fragilité qui demande protection et soin. Le signe place la préservation de la vie au premier plan et demande de reconnaître le danger avant qu''il ne devienne irréversible. Les rivalités annoncées doivent être contenues par la mesure, car une victoire obtenue dans la colère peut détruire l''équilibre du groupe. La prospérité est possible, mais sa durée dépend d''une gestion honnête des biens et du respect des engagements pris.","Le signe rappelle les devoirs envers les parents et les aînés, dont l''expérience peut prévenir des décisions lourdes de conséquences. Les déplacements exigent préparation et prudence. Un changement de lieu peut ouvrir une possibilité tout en exposant à l''isolement.","Son enseignement articule danger, conflit, prospérité et aînés. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La vigilance protège la vie","sens":"Le danger perd une part de sa force lorsqu''il est reconnu tôt et traité avec calme."},{"ordre":2,"titre":"Deux forces opposées doivent retrouver la mesure","sens":"Le conflit devient fécond lorsque chacun renonce à l''escalade et recherche une solution juste."},{"ordre":3,"titre":"La richesse demande une conduite juste","sens":"L''abondance demeure favorable lorsqu''elle circule sans orgueil, tromperie ni abus de pouvoir."},{"ordre":4,"titre":"La parole des aînés éclaire le chemin","sens":"Écouter ceux qui précèdent permet de reconnaître un danger déjà rencontré par la communauté."},{"ordre":5,"titre":"Le voyage commence par la préparation","sens":"Changer de lieu devient favorable lorsque les obligations sont accomplies et que la route est choisie avec discernement."}],"interdits":["Manger du maïs"],"prescriptions":["Honorer Sakpata et respecter les obligations qui lui sont liées","Honorer Tohossou et respecter les obligations qui lui sont liées","Préserver le dialogue familial et prendre soin des parents et des aînés","Différer les décisions prises sous l''effet de la colère et rechercher l''apaisement","Prendre au sérieux les avertissements concernant la santé et la protection de la vie"],"synthese":"YEKU TI FU réunit des enseignements liés à danger, conflit, prospérité et aînés. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
