select id, 53, 'signe_derive', null, '{"slug":"signe-052-woli-abla","nom":"WOLI ABLA","ordre":null,"type":"signe_derive","position":"52e signe du catalogue ; 36e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Woli ; signe dérivé de cette lignée","divinites":"Dan","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["WOLI ABLA appartient à la maison de Woli. Il occupe la 36e place parmi les 240 signes descendants.","Les protagonistes nommés sont Dou, Bla, Adjo et Sou. Les images centrales du récit sont le bœuf et le maïs. La prospérité est possible, mais sa durée dépend d''une gestion honnête des biens et du respect des engagements pris. La parole possède ici un pouvoir particulier : une confidence révélée, une promesse rompue ou un propos irréfléchi peut bouleverser une destinée. Le résultat annoncé dépend d''un effort régulier. La patience et la constance valent davantage qu''une réussite recherchée dans la précipitation.","Le signe appelle à se protéger des influences hostiles sans nourrir la peur ni répondre à l''agression par l''imprudence. L''accomplissement des obligations indiquées est associé à l''apaisement, à la protection et au rétablissement de l''équilibre.","Son enseignement articule prospérité, parole, travail et forces hostiles. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La richesse demande une conduite juste","sens":"L''abondance demeure favorable lorsqu''elle circule sans orgueil, tromperie ni abus de pouvoir."},{"ordre":2,"titre":"La parole mesurée préserve","sens":"Le silence et la discrétion protègent ce qui doit mûrir avant d''être rendu public."},{"ordre":3,"titre":"Le travail patient porte son fruit","sens":"Une œuvre durable se construit par des gestes répétés, ordonnés et conduits jusqu''à leur terme."},{"ordre":4,"titre":"La protection exige lucidité","sens":"La prudence, la discrétion et le respect des obligations forment une défense plus sûre que la provocation."},{"ordre":5,"titre":"L''obligation accomplie rétablit l''équilibre","sens":"Le signe relie le mieux-être à une action concrète, menée avec sérieux et continuité."}],"interdits":["Écarter les comportements imprudents signalés par le signe"],"prescriptions":["Honorer Dan et respecter les obligations qui lui sont liées","Garder les confidences et mesurer toute parole donnée"],"synthese":"WOLI ABLA réunit des enseignements liés à prospérité, parole, travail et forces hostiles. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
