select id, 70, 'signe_derive', null, '{"slug":"signe-069-di-gouda","nom":"DI GOUDA","ordre":null,"type":"signe_derive","position":"69e signe du catalogue ; 53e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Di ; signe dérivé de cette lignée","divinites":"Aucune divinité particulière n''est indiquée pour ce signe","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["DI GOUDA appartient à la maison de Di. Il occupe la 53e place parmi les 240 signes descendants.","Les protagonistes nommés sont Ganganhui, Non, Aboe et Ayo. Les images centrales du récit sont la maison, le tambour et le maïs. La prospérité est possible, mais sa durée dépend d''une gestion honnête des biens et du respect des engagements pris. La vie familiale constitue un lieu d''épreuve et d''accomplissement ; le dialogue, la fidélité et le respect des proches y sont déterminants. L''eau marque une transformation : ce qui apporte la vie peut aussi surprendre une personne insuffisamment préparée.","Le porteur est invité à relire chaque décision à la lumière de la prudence, de la responsabilité et du respect de ses obligations.","Son enseignement articule prospérité, famille et eau. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La richesse demande une conduite juste","sens":"L''abondance demeure favorable lorsqu''elle circule sans orgueil, tromperie ni abus de pouvoir."},{"ordre":2,"titre":"La paix du foyer se construit","sens":"Les liens familiaux se consolident par la patience, la parole tenue et la protection réciproque."},{"ordre":3,"titre":"L''eau transforme ce qu''elle touche","sens":"Toute force bénéfique demande une juste préparation afin que son passage nourrisse au lieu de désorganiser."}],"interdits":["Écarter les comportements imprudents signalés par le signe"],"prescriptions":["Préserver le dialogue familial et prendre soin des parents et des aînés"],"synthese":"DI GOUDA réunit des enseignements liés à prospérité, famille et eau. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
