insert into public.fa_signs (slug, name) values ('signe-070-di-sa', 'DI SA') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 71, 'signe_derive', null, '{"slug":"signe-070-di-sa","nom":"DI SA","ordre":null,"type":"signe_derive","position":"70e signe du catalogue ; 54e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Di ; signe dérivé de cette lignée","divinites":"Aucune divinité particulière n''est indiquée pour ce signe","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["DI SA appartient à la maison de Di. Il occupe la 54e place parmi les 240 signes descendants.","Les protagonistes nommés sont Houedji, Badeyiglemin, Boyi et Koudjedessa. Les images centrales du récit sont l''oiseau, le champ et la houe. Le signe place la préservation de la vie au premier plan et demande de reconnaître le danger avant qu''il ne devienne irréversible. Les rivalités annoncées doivent être contenues par la mesure, car une victoire obtenue dans la colère peut détruire l''équilibre du groupe. La vie familiale constitue un lieu d''épreuve et d''accomplissement ; le dialogue, la fidélité et le respect des proches y sont déterminants.","Le signe rappelle les devoirs envers les parents et les aînés, dont l''expérience peut prévenir des décisions lourdes de conséquences. Le résultat annoncé dépend d''un effort régulier. La patience et la constance valent davantage qu''une réussite recherchée dans la précipitation.","Son enseignement articule danger, conflit, famille et aînés. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La vigilance protège la vie","sens":"Le danger perd une part de sa force lorsqu''il est reconnu tôt et traité avec calme."},{"ordre":2,"titre":"Deux forces opposées doivent retrouver la mesure","sens":"Le conflit devient fécond lorsque chacun renonce à l''escalade et recherche une solution juste."},{"ordre":3,"titre":"La paix du foyer se construit","sens":"Les liens familiaux se consolident par la patience, la parole tenue et la protection réciproque."},{"ordre":4,"titre":"La parole des aînés éclaire le chemin","sens":"Écouter ceux qui précèdent permet de reconnaître un danger déjà rencontré par la communauté."},{"ordre":5,"titre":"Le travail patient porte son fruit","sens":"Une œuvre durable se construit par des gestes répétés, ordonnés et conduits jusqu''à leur terme."}],"interdits":["Écarter les comportements imprudents signalés par le signe"],"prescriptions":["Préserver le dialogue familial et prendre soin des parents et des aînés","Différer les décisions prises sous l''effet de la colère et rechercher l''apaisement"],"synthese":"DI SA réunit des enseignements liés à danger, conflit, famille et aînés. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
