select id, 103, 'signe_derive', null, '{"slug":"signe-102-winlin-gbo-lete","nom":"WINLIN GBO LETE","ordre":null,"type":"signe_derive","position":"102e signe du catalogue ; 86e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Winlin ; signe dérivé de cette lignée","divinites":"Aucune divinité particulière n''est indiquée pour ce signe","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["WINLIN GBO LETE appartient à la maison de Winlin. Il occupe la 86e place parmi les 240 signes descendants.","Les images centrales du récit sont la volaille, la maison et le maïs. La prospérité est possible, mais sa durée dépend d''une gestion honnête des biens et du respect des engagements pris. Le signe rappelle les devoirs envers les parents et les aînés, dont l''expérience peut prévenir des décisions lourdes de conséquences.","Le porteur est invité à relire chaque décision à la lumière de la prudence, de la responsabilité et du respect de ses obligations.","Son enseignement articule prospérité et aînés. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La richesse demande une conduite juste","sens":"L''abondance demeure favorable lorsqu''elle circule sans orgueil, tromperie ni abus de pouvoir."},{"ordre":2,"titre":"La parole des aînés éclaire le chemin","sens":"Écouter ceux qui précèdent permet de reconnaître un danger déjà rencontré par la communauté."}],"interdits":["Écarter les comportements imprudents signalés par le signe"],"prescriptions":["Préserver le dialogue familial et prendre soin des parents et des aînés"],"synthese":"WINLIN GBO LETE réunit des enseignements liés à prospérité et aînés. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
