insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 104, 'signe_derive', null, '{"slug":"signe-103-winlin-tula","nom":"WINLIN TULA","ordre":null,"type":"signe_derive","position":"103e signe du catalogue ; 87e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Winlin ; signe dérivé de cette lignée","divinites":"Fa, Ori, Lègba, Hêviosso, Gu et Lissa","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["WINLIN TULA appartient à la maison de Winlin. Il occupe la 87e place parmi les 240 signes descendants.","Ce signe relie le changement propre à Winlin à la recherche d''orientation portée par Tula. Il annonce une capacité à guider, à prendre des responsabilités et à ouvrir une voie utile au groupe.","La réussite dépend toutefois de la sobriété, de la fidélité dans le couple et de la maîtrise des réactions excessives. Une dette ou un différend financier ne doit jamais être réglé par la contrainte.","Le porteur est invité à servir sa destinée avec constance, à protéger ses proches et à exercer son influence dans un esprit d''équité."],"devises":[{"ordre":1,"titre":"La destinée s''affermit par la maîtrise de soi","sens":"L''élévation annoncée demande une conduite stable, sobre et fidèle aux engagements pris."},{"ordre":2,"titre":"L''autorité protège avant de commander","sens":"Le responsable gagne le respect en servant la communauté et en préservant les plus vulnérables."},{"ordre":3,"titre":"Une dette ne se règle pas par la force","sens":"La contrainte transforme un désaccord matériel en conflit durable ; le dialogue et la justice doivent primer."}],"interdits":["Consommer de l''alcool","Commettre l''adultère","Employer la force pour recouvrer une dette","Agir sous l''effet d''une excitation excessive"],"prescriptions":["Honorer Fa et Ori","Respecter les obligations liées à Lègba, Hêviosso, Gu et Lissa","Exercer toute responsabilité avec mesure et esprit de service"],"synthese":"WINLIN TULA développe des thèmes liés à destinée, maîtrise de soi, autorité et service de la communauté. Le porteur doit respecter ses interdits, accomplir les obligations indiquées et conduire ses choix avec mesure afin de préserver son équilibre."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
