insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 107, 'signe_derive', null, '{"slug":"signe-106-winlin-ka","nom":"WINLIN KA","ordre":null,"type":"signe_derive","position":"106e signe du catalogue ; 90e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Winlin ; signe dérivé de cette lignée","divinites":"Fa, Lègba et Hêviosso","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["WINLIN KA appartient à la maison de Winlin. Il occupe la 90e place parmi les 240 signes descendants.","Winlin Ka enseigne que le bien comme le mal peuvent entrer par la même porte. Le porteur doit donc rester attentif aux influences qu''il accueille dans sa maison et dans ses décisions.","Le signe met en garde contre l''ingratitude, l''avarice et l''infidélité. Il rappelle aussi que le tort infligé à autrui finit par revenir vers son auteur.","L''unité des frères et sœurs, l''hospitalité raisonnable et le respect des parents sont présentés comme des appuis essentiels pour recevoir et conserver la prospérité."],"devises":[{"ordre":1,"titre":"La porte accueille le favorable comme le nuisible","sens":"Le discernement doit accompagner toute nouvelle relation, proposition ou promesse."},{"ordre":2,"titre":"Le mal fait à autrui revient vers son auteur","sens":"Chaque acte prépare une conséquence ; la prudence et la justice protègent mieux que la vengeance."},{"ordre":3,"titre":"L''avarice retarde la fortune","sens":"Un bien retenu sans mesure peut isoler son propriétaire et fermer les chemins de la prospérité."}],"interdits":["Céder à l''avarice","Trahir son conjoint","Faire du mal à une personne vulnérable","Ignorer les conseils des parents"],"prescriptions":["Préserver l''unité familiale","Honorer Fa, Lègba et Hêviosso","Partager avec mesure et accueillir les proches sans désorganiser le foyer"],"synthese":"WINLIN KA développe des thèmes liés à gratitude, unité familiale, juste usage des biens et retour des actes. Le porteur doit respecter ses interdits, accomplir les obligations indiquées et conduire ses choix avec mesure afin de préserver son équilibre."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
