insert into public.fa_signs (slug, name) values ('signe-111-abla-losso', 'ABLA LOSSO') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 112, 'signe_derive', null, '{"slug":"signe-111-abla-losso","nom":"ABLA LOSSO","ordre":null,"type":"signe_derive","position":"111e signe du catalogue ; 95e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Abla ; signe dérivé de cette lignée","divinites":"Dan, Hêviosso","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["ABLA LOSSO appartient à la maison de Abla. Il occupe la 95e place parmi les 240 signes descendants.","Les images centrales du récit sont le maïs. La vie familiale constitue un lieu d''épreuve et d''accomplissement ; le dialogue, la fidélité et le respect des proches y sont déterminants. Le signe rappelle les devoirs envers les parents et les aînés, dont l''expérience peut prévenir des décisions lourdes de conséquences. La maternité et la naissance appellent une protection particulière, ainsi que le respect strict des recommandations reçues.","Le signe appelle à se protéger des influences hostiles sans nourrir la peur ni répondre à l''agression par l''imprudence. L''accomplissement des obligations indiquées est associé à l''apaisement, à la protection et au rétablissement de l''équilibre.","Son enseignement articule famille, aînés, maternité et forces hostiles. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La paix du foyer se construit","sens":"Les liens familiaux se consolident par la patience, la parole tenue et la protection réciproque."},{"ordre":2,"titre":"La parole des aînés éclaire le chemin","sens":"Écouter ceux qui précèdent permet de reconnaître un danger déjà rencontré par la communauté."},{"ordre":3,"titre":"La naissance se protège avec attention","sens":"La vie en formation demande prudence, accompagnement et accomplissement des obligations indiquées."},{"ordre":4,"titre":"La protection exige lucidité","sens":"La prudence, la discrétion et le respect des obligations forment une défense plus sûre que la provocation."},{"ordre":5,"titre":"L''obligation accomplie rétablit l''équilibre","sens":"Le signe relie le mieux-être à une action concrète, menée avec sérieux et continuité."}],"interdits":["Écarter les comportements imprudents signalés par le signe"],"prescriptions":["Accomplir avec sérieux les sacrifices et offrandes prescrits","Honorer Dan et respecter les obligations qui lui sont liées","Honorer Hêviosso et respecter les obligations qui lui sont liées","Préserver le dialogue familial et prendre soin des parents et des aînés","Prendre au sérieux les avertissements concernant la santé et la protection de la vie"],"synthese":"ABLA LOSSO réunit des enseignements liés à famille, aînés, maternité et forces hostiles. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
