insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 124, 'signe_derive', null, '{"slug":"signe-123-aklan-yekou","nom":"AKLAN-YEKOU","ordre":null,"type":"signe_derive","position":"123e signe du catalogue ; 107e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Aklan ; signe dérivé de cette lignée","divinites":"Hoho, Kluvito","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["AKLAN-YEKOU appartient à la maison de Aklan. Il occupe la 107e place parmi les 240 signes descendants.","Les images centrales du récit sont la terre. Son déroulement met en jeu une épreuve où la vie et la mort sont mises en balance. Le signe place la préservation de la vie au premier plan et demande de reconnaître le danger avant qu''il ne devienne irréversible. Une confiance mal placée peut exposer le porteur à la ruse ou à la trahison ; il lui faut observer les actes autant que les paroles. Le résultat annoncé dépend d''un effort régulier. La patience et la constance valent davantage qu''une réussite recherchée dans la précipitation.","L''eau marque une transformation : ce qui apporte la vie peut aussi surprendre une personne insuffisamment préparée. L''accomplissement des obligations indiquées est associé à l''apaisement, à la protection et au rétablissement de l''équilibre.","Son enseignement articule danger, trahison, travail et eau. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La vigilance protège la vie","sens":"Le danger perd une part de sa force lorsqu''il est reconnu tôt et traité avec calme."},{"ordre":2,"titre":"La confiance se donne avec discernement","sens":"La loyauté se vérifie dans les actes. Le signe invite à rester ouvert sans ignorer les indices d''une intention cachée."},{"ordre":3,"titre":"Le travail patient porte son fruit","sens":"Une œuvre durable se construit par des gestes répétés, ordonnés et conduits jusqu''à leur terme."},{"ordre":4,"titre":"L''eau transforme ce qu''elle touche","sens":"Toute force bénéfique demande une juste préparation afin que son passage nourrisse au lieu de désorganiser."},{"ordre":5,"titre":"L''obligation accomplie rétablit l''équilibre","sens":"Le signe relie le mieux-être à une action concrète, menée avec sérieux et continuité."}],"interdits":["Écarter les comportements imprudents signalés par le signe"],"prescriptions":["Honorer Hoho et respecter les obligations qui lui sont liées","Honorer Kluvito et respecter les obligations qui lui sont liées"],"synthese":"AKLAN-YEKOU réunit des enseignements liés à danger, trahison, travail et eau. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
