insert into public.fa_signs (slug, name) values ('signe-128-aklan-do-abla', 'AKLAN DO ABLA') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 129, 'signe_derive', null, '{"slug":"signe-128-aklan-do-abla","nom":"AKLAN DO ABLA","ordre":null,"type":"signe_derive","position":"128e signe du catalogue ; 112e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Aklan ; signe dérivé de cette lignée","divinites":"Dan, Hoho","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["AKLAN DO ABLA appartient à la maison de Aklan. Il occupe la 112e place parmi les 240 signes descendants.","Les images centrales du récit sont la corde. Son déroulement met en jeu une question d''autorité, de succession ou de gouvernement. Une confiance mal placée peut exposer le porteur à la ruse ou à la trahison ; il lui faut observer les actes autant que les paroles. Une fonction d''autorité peut se présenter. Elle doit servir la communauté et s''exercer sans précipitation ni domination. L''eau marque une transformation : ce qui apporte la vie peut aussi surprendre une personne insuffisamment préparée.","Les relations d''amitié sont mises à l''épreuve. Le porteur doit distinguer la solidarité véritable d''une proximité intéressée. L''accomplissement des obligations indiquées est associé à l''apaisement, à la protection et au rétablissement de l''équilibre.","Son enseignement articule trahison, autorité, eau et amitié. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La confiance se donne avec discernement","sens":"La loyauté se vérifie dans les actes. Le signe invite à rester ouvert sans ignorer les indices d''une intention cachée."},{"ordre":2,"titre":"Le commandement se prouve par l''équité","sens":"Diriger engage la responsabilité du porteur envers ceux qui dépendent de ses décisions."},{"ordre":3,"titre":"L''eau transforme ce qu''elle touche","sens":"Toute force bénéfique demande une juste préparation afin que son passage nourrisse au lieu de désorganiser."},{"ordre":4,"titre":"L''amitié se reconnaît dans l''épreuve","sens":"Un compagnon loyal protège et conseille ; une relation fondée sur l''intérêt se révèle lorsque survient le danger."},{"ordre":5,"titre":"L''obligation accomplie rétablit l''équilibre","sens":"Le signe relie le mieux-être à une action concrète, menée avec sérieux et continuité."}],"interdits":["Écarter les comportements imprudents signalés par le signe"],"prescriptions":["Honorer Dan et respecter les obligations qui lui sont liées","Honorer Hoho et respecter les obligations qui lui sont liées"],"synthese":"AKLAN DO ABLA réunit des enseignements liés à trahison, autorité, eau et amitié. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
