select id, 130, 'signe_derive', null, '{"slug":"signe-129-aklan-gouda","nom":"AKLAN GOUDA","ordre":null,"type":"signe_derive","position":"129e signe du catalogue ; 113e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Aklan ; signe dérivé de cette lignée","divinites":"Hoho","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["AKLAN GOUDA appartient à la maison de Aklan. Il occupe la 113e place parmi les 240 signes descendants.","Les images centrales du récit sont le marché et l''igname. Son déroulement met en jeu une question d''autorité, de succession ou de gouvernement. Une confiance mal placée peut exposer le porteur à la ruse ou à la trahison ; il lui faut observer les actes autant que les paroles. La prospérité est possible, mais sa durée dépend d''une gestion honnête des biens et du respect des engagements pris. Une fonction d''autorité peut se présenter. Elle doit servir la communauté et s''exercer sans précipitation ni domination.","L''eau marque une transformation : ce qui apporte la vie peut aussi surprendre une personne insuffisamment préparée. L''accomplissement des obligations indiquées est associé à l''apaisement, à la protection et au rétablissement de l''équilibre.","Son enseignement articule trahison, prospérité, autorité et eau. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La confiance se donne avec discernement","sens":"La loyauté se vérifie dans les actes. Le signe invite à rester ouvert sans ignorer les indices d''une intention cachée."},{"ordre":2,"titre":"La richesse demande une conduite juste","sens":"L''abondance demeure favorable lorsqu''elle circule sans orgueil, tromperie ni abus de pouvoir."},{"ordre":3,"titre":"Le commandement se prouve par l''équité","sens":"Diriger engage la responsabilité du porteur envers ceux qui dépendent de ses décisions."},{"ordre":4,"titre":"L''eau transforme ce qu''elle touche","sens":"Toute force bénéfique demande une juste préparation afin que son passage nourrisse au lieu de désorganiser."},{"ordre":5,"titre":"L''obligation accomplie rétablit l''équilibre","sens":"Le signe relie le mieux-être à une action concrète, menée avec sérieux et continuité."}],"interdits":["Manger du poulet"],"prescriptions":["Honorer Hoho et respecter les obligations qui lui sont liées"],"synthese":"AKLAN GOUDA réunit des enseignements liés à trahison, prospérité, autorité et eau. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
