insert into public.fa_signs (slug, name) values ('signe-130-aklan-don-sa', 'AKLAN-DON-SA') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 131, 'signe_derive', null, '{"slug":"signe-130-aklan-don-sa","nom":"AKLAN-DON-SA","ordre":null,"type":"signe_derive","position":"130e signe du catalogue ; 114e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Aklan ; signe dérivé de cette lignée","divinites":"Dan, Hoho","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["AKLAN-DON-SA appartient à la maison de Aklan. Il occupe la 114e place parmi les 240 signes descendants.","Les images centrales du récit sont la terre et le maïs. Son déroulement met en jeu une opposition dont l''issue dépend de la maîtrise de soi puis une recherche de prospérité qui éprouve l''intégrité. Les rivalités annoncées doivent être contenues par la mesure, car une victoire obtenue dans la colère peut détruire l''équilibre du groupe. La prospérité est possible, mais sa durée dépend d''une gestion honnête des biens et du respect des engagements pris. Le signe rappelle les devoirs envers les parents et les aînés, dont l''expérience peut prévenir des décisions lourdes de conséquences.","L''eau marque une transformation : ce qui apporte la vie peut aussi surprendre une personne insuffisamment préparée. L''accomplissement des obligations indiquées est associé à l''apaisement, à la protection et au rétablissement de l''équilibre.","Son enseignement articule conflit, prospérité, aînés et eau. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"Deux forces opposées doivent retrouver la mesure","sens":"Le conflit devient fécond lorsque chacun renonce à l''escalade et recherche une solution juste."},{"ordre":2,"titre":"La richesse demande une conduite juste","sens":"L''abondance demeure favorable lorsqu''elle circule sans orgueil, tromperie ni abus de pouvoir."},{"ordre":3,"titre":"La parole des aînés éclaire le chemin","sens":"Écouter ceux qui précèdent permet de reconnaître un danger déjà rencontré par la communauté."},{"ordre":4,"titre":"L''eau transforme ce qu''elle touche","sens":"Toute force bénéfique demande une juste préparation afin que son passage nourrisse au lieu de désorganiser."},{"ordre":5,"titre":"L''obligation accomplie rétablit l''équilibre","sens":"Le signe relie le mieux-être à une action concrète, menée avec sérieux et continuité."}],"interdits":["Manger du haricot","Manger du maïs"],"prescriptions":["Honorer Dan et respecter les obligations qui lui sont liées","Honorer Hoho et respecter les obligations qui lui sont liées","Préserver le dialogue familial et prendre soin des parents et des aînés","Différer les décisions prises sous l''effet de la colère et rechercher l''apaisement"],"synthese":"AKLAN-DON-SA réunit des enseignements liés à conflit, prospérité, aînés et eau. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
