select id, 137, 'signe_derive', null, '{"slug":"signe-136-aklan-kpa-fou","nom":"AKLAN KPA FOU","ordre":null,"type":"signe_derive","position":"136e signe du catalogue ; 120e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Aklan ; signe dérivé de cette lignée","divinites":"Dan, Hoho","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["AKLAN KPA FOU appartient à la maison de Aklan. Il occupe la 120e place parmi les 240 signes descendants.","Les images centrales du récit sont la gazelle, la maison, le couteau et le maïs. Son déroulement met en jeu une consultation destinée à éclairer une décision, une épreuve où la vie et la mort sont mises en balance puis une manœuvre cachée qui met la loyauté à l''épreuve. Le signe place la préservation de la vie au premier plan et demande de reconnaître le danger avant qu''il ne devienne irréversible. Une confiance mal placée peut exposer le porteur à la ruse ou à la trahison ; il lui faut observer les actes autant que les paroles. La vie familiale constitue un lieu d''épreuve et d''accomplissement ; le dialogue, la fidélité et le respect des proches y sont déterminants.","Le signe rappelle les devoirs envers les parents et les aînés, dont l''expérience peut prévenir des décisions lourdes de conséquences. La parole possède ici un pouvoir particulier : une confidence révélée, une promesse rompue ou un propos irréfléchi peut bouleverser une destinée.","Son enseignement articule danger, trahison, famille et aînés. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La vigilance protège la vie","sens":"Le danger perd une part de sa force lorsqu''il est reconnu tôt et traité avec calme."},{"ordre":2,"titre":"La confiance se donne avec discernement","sens":"La loyauté se vérifie dans les actes. Le signe invite à rester ouvert sans ignorer les indices d''une intention cachée."},{"ordre":3,"titre":"La paix du foyer se construit","sens":"Les liens familiaux se consolident par la patience, la parole tenue et la protection réciproque."},{"ordre":4,"titre":"La parole des aînés éclaire le chemin","sens":"Écouter ceux qui précèdent permet de reconnaître un danger déjà rencontré par la communauté."},{"ordre":5,"titre":"La parole mesurée préserve","sens":"Le silence et la discrétion protègent ce qui doit mûrir avant d''être rendu public."}],"interdits":["Manger de la viande de bœuf"],"prescriptions":["Honorer Dan et respecter les obligations qui lui sont liées","Honorer Hoho et respecter les obligations qui lui sont liées","Préserver le dialogue familial et prendre soin des parents et des aînés","Garder les confidences et mesurer toute parole donnée"],"synthese":"AKLAN KPA FOU réunit des enseignements liés à danger, trahison, famille et aînés. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
