select id, 154, 'signe_derive', null, '{"slug":"signe-153-sa-yekou","nom":"SA YEKOU","ordre":null,"type":"signe_derive","position":"153e signe du catalogue ; 137e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Sa ; signe dérivé de cette lignée","divinites":"Aucune divinité particulière n''est indiquée pour ce signe","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["SA YEKOU appartient à la maison de Sa. Il occupe la 137e place parmi les 240 signes descendants.","Son déroulement met en jeu une opposition dont l''issue dépend de la maîtrise de soi. Les rivalités annoncées doivent être contenues par la mesure, car une victoire obtenue dans la colère peut détruire l''équilibre du groupe. Une fonction d''autorité peut se présenter. Elle doit servir la communauté et s''exercer sans précipitation ni domination. L''accomplissement des obligations indiquées est associé à l''apaisement, à la protection et au rétablissement de l''équilibre.","Le porteur est invité à relire chaque décision à la lumière de la prudence, de la responsabilité et du respect de ses obligations.","Son enseignement articule conflit, autorité et obligations. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"Deux forces opposées doivent retrouver la mesure","sens":"Le conflit devient fécond lorsque chacun renonce à l''escalade et recherche une solution juste."},{"ordre":2,"titre":"Le commandement se prouve par l''équité","sens":"Diriger engage la responsabilité du porteur envers ceux qui dépendent de ses décisions."},{"ordre":3,"titre":"L''obligation accomplie rétablit l''équilibre","sens":"Le signe relie le mieux-être à une action concrète, menée avec sérieux et continuité."}],"interdits":["Écarter les comportements imprudents signalés par le signe"],"prescriptions":["Accomplir avec sérieux les sacrifices et offrandes prescrits","Différer les décisions prises sous l''effet de la colère et rechercher l''apaisement"],"synthese":"SA YEKOU réunit des enseignements liés à conflit, autorité et obligations. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
