select id, 156, 'signe_derive', null, '{"slug":"signe-155-sa-di","nom":"SA-DI","ordre":null,"type":"signe_derive","position":"155e signe du catalogue ; 139e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Sa ; signe dérivé de cette lignée","divinites":"Aucune divinité particulière n''est indiquée pour ce signe","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["SA-DI appartient à la maison de Sa. Il occupe la 139e place parmi les 240 signes descendants.","L''enseignement part d''une situation ordinaire et en révèle les conséquences morales et spirituelles. Le signe place la préservation de la vie au premier plan et demande de reconnaître le danger avant qu''il ne devienne irréversible. L''eau marque une transformation : ce qui apporte la vie peut aussi surprendre une personne insuffisamment préparée. L''accomplissement des obligations indiquées est associé à l''apaisement, à la protection et au rétablissement de l''équilibre.","Le porteur est invité à relire chaque décision à la lumière de la prudence, de la responsabilité et du respect de ses obligations.","Son enseignement articule danger, eau et obligations. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La vigilance protège la vie","sens":"Le danger perd une part de sa force lorsqu''il est reconnu tôt et traité avec calme."},{"ordre":2,"titre":"L''eau transforme ce qu''elle touche","sens":"Toute force bénéfique demande une juste préparation afin que son passage nourrisse au lieu de désorganiser."},{"ordre":3,"titre":"L''obligation accomplie rétablit l''équilibre","sens":"Le signe relie le mieux-être à une action concrète, menée avec sérieux et continuité."}],"interdits":["Écarter les comportements imprudents signalés par le signe"],"prescriptions":["Accomplir avec sérieux les sacrifices et offrandes prescrits"],"synthese":"SA-DI réunit des enseignements liés à danger, eau et obligations. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
