select id, 159, 'signe_derive', null, '{"slug":"signe-158-sa-abla","nom":"SA ABLA","ordre":null,"type":"signe_derive","position":"158e signe du catalogue ; 142e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Sa ; signe dérivé de cette lignée","divinites":"Fa, les ancêtres et Yalodé","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["SA ABLA appartient à la maison de Sa. Il occupe la 142e place parmi les 240 signes descendants.","Sa Abla oppose la force immédiate à l''intelligence qui observe avant d''agir. Le signe annonce une possibilité de prospérité, à condition de stabiliser les décisions et d''accomplir les obligations indiquées.","Il attire l''attention sur la santé physique et spirituelle. Un avertissement du corps, un conseil reçu ou une difficulté persistante ne doit pas être traité avec négligence.","La gratitude, l''hospitalité et le travail honnête soutiennent l''équilibre du porteur. Les conflits sans nécessité et le mauvais traitement des visiteurs fragilisent au contraire sa position."],"devises":[{"ordre":1,"titre":"L''intelligence doit conduire la force","sens":"La stratégie et la patience obtiennent ce que l''impulsion risque de compromettre."},{"ordre":2,"titre":"La prospérité a besoin de stabilité","sens":"Une bénédiction se conserve par la discipline, la gratitude et l''accomplissement des obligations."},{"ordre":3,"titre":"Le corps et l''esprit doivent être écoutés","sens":"Prendre au sérieux les premiers avertissements permet de prévenir une épreuve plus lourde."}],"interdits":["Provoquer un conflit sans nécessité","Négliger un avertissement concernant la santé","Maltraiter un visiteur","Agir avec ingratitude"],"prescriptions":["Accomplir les sacrifices prescrits","Honorer les ancêtres et Yalodé","Privilégier l''intelligence, le travail honnête et la gratitude"],"synthese":"SA ABLA développe des thèmes liés à intelligence, maîtrise de la force, santé, gratitude et prospérité. Le porteur doit respecter ses interdits, accomplir les obligations indiquées et conduire ses choix avec mesure afin de préserver son équilibre."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
