select id, 189, 'signe_derive', null, '{"slug":"signe-188-toula-abla","nom":"TOULA ABLA","ordre":null,"type":"signe_derive","position":"188e signe du catalogue ; 172e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Tula ; signe dérivé de cette lignée","divinites":"Dan","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["TOULA ABLA appartient à la maison de Tula. Il occupe la 172e place parmi les 240 signes descendants.","Les images centrales du récit sont le bœuf, la maison et le maïs. Le signe rappelle les devoirs envers les parents et les aînés, dont l''expérience peut prévenir des décisions lourdes de conséquences. La maternité et la naissance appellent une protection particulière, ainsi que le respect strict des recommandations reçues. L''accomplissement des obligations indiquées est associé à l''apaisement, à la protection et au rétablissement de l''équilibre.","Le porteur est invité à relire chaque décision à la lumière de la prudence, de la responsabilité et du respect de ses obligations.","Son enseignement articule aînés, maternité et obligations. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La parole des aînés éclaire le chemin","sens":"Écouter ceux qui précèdent permet de reconnaître un danger déjà rencontré par la communauté."},{"ordre":2,"titre":"La naissance se protège avec attention","sens":"La vie en formation demande prudence, accompagnement et accomplissement des obligations indiquées."},{"ordre":3,"titre":"L''obligation accomplie rétablit l''équilibre","sens":"Le signe relie le mieux-être à une action concrète, menée avec sérieux et continuité."}],"interdits":["Écarter les comportements imprudents signalés par le signe"],"prescriptions":["Accomplir avec sérieux les sacrifices et offrandes prescrits","Honorer Dan et respecter les obligations qui lui sont liées","Préserver le dialogue familial et prendre soin des parents et des aînés","Prendre au sérieux les avertissements concernant la santé et la protection de la vie"],"synthese":"TOULA ABLA réunit des enseignements liés à aînés, maternité et obligations. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
