insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 191, 'signe_derive', null, '{"slug":"signe-190-toula-gouda","nom":"TOULA GOUDA","ordre":null,"type":"signe_derive","position":"190e signe du catalogue ; 174e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Tula ; signe dérivé de cette lignée","divinites":"Dan","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["TOULA GOUDA appartient à la maison de Tula. Il occupe la 174e place parmi les 240 signes descendants.","Les images centrales du récit sont le maïs. Son déroulement met en jeu l''accomplissement d''une obligation rituelle, une épreuve où la vie et la mort sont mises en balance puis une question d''autorité, de succession ou de gouvernement. Le signe place la préservation de la vie au premier plan et demande de reconnaître le danger avant qu''il ne devienne irréversible. Une fonction d''autorité peut se présenter. Elle doit servir la communauté et s''exercer sans précipitation ni domination. L''intégrité constitue une protection essentielle. Le gain obtenu par le mensonge ou l''appropriation du bien d''autrui finit par fragiliser son auteur.","L''accomplissement des obligations indiquées est associé à l''apaisement, à la protection et au rétablissement de l''équilibre.","Son enseignement articule danger, autorité, intégrité et obligations. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La vigilance protège la vie","sens":"Le danger perd une part de sa force lorsqu''il est reconnu tôt et traité avec calme."},{"ordre":2,"titre":"Le commandement se prouve par l''équité","sens":"Diriger engage la responsabilité du porteur envers ceux qui dépendent de ses décisions."},{"ordre":3,"titre":"Le bien d''autrui ne fonde aucune réussite","sens":"La prospérité durable se construit par l''honnêteté et le respect des droits de chacun."},{"ordre":4,"titre":"L''obligation accomplie rétablit l''équilibre","sens":"Le signe relie le mieux-être à une action concrète, menée avec sérieux et continuité."}],"interdits":["Écarter les comportements imprudents signalés par le signe"],"prescriptions":["Honorer Dan et respecter les obligations qui lui sont liées"],"synthese":"TOULA GOUDA réunit des enseignements liés à danger, autorité, intégrité et obligations. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
