insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 192, 'signe_derive', null, '{"slug":"signe-191-toula-sa","nom":"TOULA SA","ordre":null,"type":"signe_derive","position":"191e signe du catalogue ; 175e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Tula ; signe dérivé de cette lignée","divinites":"Aucune divinité particulière n''est indiquée pour ce signe","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["TOULA SA appartient à la maison de Tula. Il occupe la 175e place parmi les 240 signes descendants.","Les images centrales du récit sont le poisson, la mer, le vent et le maïs. Son déroulement met en jeu une consultation destinée à éclairer une décision, une épreuve où la vie et la mort sont mises en balance puis une question d''autorité, de succession ou de gouvernement. Le signe place la préservation de la vie au premier plan et demande de reconnaître le danger avant qu''il ne devienne irréversible. Une confiance mal placée peut exposer le porteur à la ruse ou à la trahison ; il lui faut observer les actes autant que les paroles. Une fonction d''autorité peut se présenter. Elle doit servir la communauté et s''exercer sans précipitation ni domination.","La vie familiale constitue un lieu d''épreuve et d''accomplissement ; le dialogue, la fidélité et le respect des proches y sont déterminants. La parole possède ici un pouvoir particulier : une confidence révélée, une promesse rompue ou un propos irréfléchi peut bouleverser une destinée.","Son enseignement articule danger, trahison, autorité et famille. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La vigilance protège la vie","sens":"Le danger perd une part de sa force lorsqu''il est reconnu tôt et traité avec calme."},{"ordre":2,"titre":"La confiance se donne avec discernement","sens":"La loyauté se vérifie dans les actes. Le signe invite à rester ouvert sans ignorer les indices d''une intention cachée."},{"ordre":3,"titre":"Le commandement se prouve par l''équité","sens":"Diriger engage la responsabilité du porteur envers ceux qui dépendent de ses décisions."},{"ordre":4,"titre":"La paix du foyer se construit","sens":"Les liens familiaux se consolident par la patience, la parole tenue et la protection réciproque."},{"ordre":5,"titre":"La parole mesurée préserve","sens":"Le silence et la discrétion protègent ce qui doit mûrir avant d''être rendu public."}],"interdits":["Écarter les comportements imprudents signalés par le signe"],"prescriptions":["Préserver le dialogue familial et prendre soin des parents et des aînés","Garder les confidences et mesurer toute parole donnée"],"synthese":"TOULA SA réunit des enseignements liés à danger, trahison, autorité et famille. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
