select id, 197, 'signe_derive', null, '{"slug":"signe-196-toula-fu","nom":"TOULA FU","ordre":null,"type":"signe_derive","position":"196e signe du catalogue ; 180e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Tula ; signe dérivé de cette lignée","divinites":"Dan","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["TOULA FU appartient à la maison de Tula. Il occupe la 180e place parmi les 240 signes descendants.","L''enseignement part d''une situation ordinaire et en révèle les conséquences morales et spirituelles. L''eau marque une transformation : ce qui apporte la vie peut aussi surprendre une personne insuffisamment préparée. Le signe appelle à se protéger des influences hostiles sans nourrir la peur ni répondre à l''agression par l''imprudence. L''accomplissement des obligations indiquées est associé à l''apaisement, à la protection et au rétablissement de l''équilibre.","Le porteur est invité à relire chaque décision à la lumière de la prudence, de la responsabilité et du respect de ses obligations.","Son enseignement articule eau, forces hostiles et obligations. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"L''eau transforme ce qu''elle touche","sens":"Toute force bénéfique demande une juste préparation afin que son passage nourrisse au lieu de désorganiser."},{"ordre":2,"titre":"La protection exige lucidité","sens":"La prudence, la discrétion et le respect des obligations forment une défense plus sûre que la provocation."},{"ordre":3,"titre":"L''obligation accomplie rétablit l''équilibre","sens":"Le signe relie le mieux-être à une action concrète, menée avec sérieux et continuité."}],"interdits":["Écarter les comportements imprudents signalés par le signe"],"prescriptions":["Accomplir avec sérieux les sacrifices et offrandes prescrits","Honorer Dan et respecter les obligations qui lui sont liées"],"synthese":"TOULA FU réunit des enseignements liés à eau, forces hostiles et obligations. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
