insert into public.fa_signs (slug, name) values ('signe-197-leta-yi-gbe-lete-gbe', 'LETA YI GBE / LETE GBE') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 198, 'signe_derive', null, '{"slug":"signe-197-leta-yi-gbe-lete-gbe","nom":"LETA YI GBE / LETE GBE","ordre":null,"type":"signe_derive","position":"197e signe du catalogue ; 181e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Lètè ; signe dérivé de cette lignée","divinites":"Lègba, Sakpata","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["LETA YI GBE / LETE GBE appartient à la maison de Lètè. Il occupe la 181e place parmi les 240 signes descendants.","Les images centrales du récit sont l''escargot et le maïs. Son déroulement met en jeu une épreuve où la vie et la mort sont mises en balance. Le signe place la préservation de la vie au premier plan et demande de reconnaître le danger avant qu''il ne devienne irréversible. La vie familiale constitue un lieu d''épreuve et d''accomplissement ; le dialogue, la fidélité et le respect des proches y sont déterminants. La parole possède ici un pouvoir particulier : une confidence révélée, une promesse rompue ou un propos irréfléchi peut bouleverser une destinée.","L''eau marque une transformation : ce qui apporte la vie peut aussi surprendre une personne insuffisamment préparée. L''accomplissement des obligations indiquées est associé à l''apaisement, à la protection et au rétablissement de l''équilibre.","Son enseignement articule danger, famille, parole et eau. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La vigilance protège la vie","sens":"Le danger perd une part de sa force lorsqu''il est reconnu tôt et traité avec calme."},{"ordre":2,"titre":"La paix du foyer se construit","sens":"Les liens familiaux se consolident par la patience, la parole tenue et la protection réciproque."},{"ordre":3,"titre":"La parole mesurée préserve","sens":"Le silence et la discrétion protègent ce qui doit mûrir avant d''être rendu public."},{"ordre":4,"titre":"L''eau transforme ce qu''elle touche","sens":"Toute force bénéfique demande une juste préparation afin que son passage nourrisse au lieu de désorganiser."},{"ordre":5,"titre":"L''obligation accomplie rétablit l''équilibre","sens":"Le signe relie le mieux-être à une action concrète, menée avec sérieux et continuité."}],"interdits":["Manger de l''escargot"],"prescriptions":["Honorer Lègba et respecter les obligations qui lui sont liées","Honorer Sakpata et respecter les obligations qui lui sont liées","Préserver le dialogue familial et prendre soin des parents et des aînés","Garder les confidences et mesurer toute parole donnée"],"synthese":"LETA YI GBE / LETE GBE réunit des enseignements liés à danger, famille, parole et eau. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
