select id, 199, 'signe_derive', null, '{"slug":"signe-198-lete-yekou","nom":"LETE YEKOU","ordre":null,"type":"signe_derive","position":"198e signe du catalogue ; 182e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Lètè ; signe dérivé de cette lignée","divinites":"Fa, Ori et Kluvito","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["LETE YEKOU appartient à la maison de Lètè. Il occupe la 182e place parmi les 240 signes descendants.","Lètè Yèku unit la persévérance de Lètè à la profondeur ancestrale de Yèku. Il invite le porteur à rechercher des bases solides avant de poursuivre une ambition matérielle.","Les anciens, les défunts et l''histoire familiale constituent des repères. Une rupture avec cette mémoire peut créer instabilité, isolement ou perte de direction.","La prospérité annoncée se construit lentement. Elle demande discipline, respect de la parole donnée et attention aux conséquences d''une décision prise dans le secret ou la précipitation."],"devises":[{"ordre":1,"titre":"Les ancêtres gardent la clé des fondations","sens":"La mémoire familiale aide à comprendre les épreuves présentes et à choisir une voie plus stable."},{"ordre":2,"titre":"La fortune durable avance sans précipitation","sens":"La patience, l''épargne et la constance protègent mieux qu''un gain rapide."},{"ordre":3,"titre":"La parole tenue consolide la maison","sens":"Un engagement respecté nourrit la confiance entre les générations et protège la réputation."}],"interdits":["Négliger les devoirs envers les défunts et les ancêtres","Rechercher un gain rapide au détriment de la stabilité","Rompre une promesse importante"],"prescriptions":["Honorer Kluvito et entretenir la mémoire familiale","Prendre soin de Ori et suivre les orientations de Fa","Construire toute entreprise sur des engagements clairs et durables"],"synthese":"LETE YEKOU développe des thèmes liés à mémoire ancestrale, stabilité, prudence et prospérité durable. Le porteur doit respecter ses interdits, accomplir les obligations indiquées et conduire ses choix avec mesure afin de préserver son équilibre."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
