select id, 213, 'signe_derive', null, '{"slug":"signe-212-ka-wo-gbe","nom":"KA WO GBE","ordre":null,"type":"signe_derive","position":"212e signe du catalogue ; 196e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Ka ; signe dérivé de cette lignée","divinites":"Hoho, Kluvito","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["KA WO GBE appartient à la maison de Ka. Il occupe la 196e place parmi les 240 signes descendants.","Les images centrales du récit sont la maison et le maïs. Son déroulement met en jeu l''accomplissement d''une obligation rituelle puis une consultation destinée à éclairer une décision. La prospérité est possible, mais sa durée dépend d''une gestion honnête des biens et du respect des engagements pris. La vie familiale constitue un lieu d''épreuve et d''accomplissement ; le dialogue, la fidélité et le respect des proches y sont déterminants. Le signe rappelle les devoirs envers les parents et les aînés, dont l''expérience peut prévenir des décisions lourdes de conséquences.","L''eau marque une transformation : ce qui apporte la vie peut aussi surprendre une personne insuffisamment préparée. Les relations d''amitié sont mises à l''épreuve. Le porteur doit distinguer la solidarité véritable d''une proximité intéressée.","Son enseignement articule prospérité, famille, aînés et eau. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La richesse demande une conduite juste","sens":"L''abondance demeure favorable lorsqu''elle circule sans orgueil, tromperie ni abus de pouvoir."},{"ordre":2,"titre":"La paix du foyer se construit","sens":"Les liens familiaux se consolident par la patience, la parole tenue et la protection réciproque."},{"ordre":3,"titre":"La parole des aînés éclaire le chemin","sens":"Écouter ceux qui précèdent permet de reconnaître un danger déjà rencontré par la communauté."},{"ordre":4,"titre":"L''eau transforme ce qu''elle touche","sens":"Toute force bénéfique demande une juste préparation afin que son passage nourrisse au lieu de désorganiser."},{"ordre":5,"titre":"L''amitié se reconnaît dans l''épreuve","sens":"Un compagnon loyal protège et conseille ; une relation fondée sur l''intérêt se révèle lorsque survient le danger."}],"interdits":["Écarter les comportements imprudents signalés par le signe"],"prescriptions":["Honorer Hoho et respecter les obligations qui lui sont liées","Honorer Kluvito et respecter les obligations qui lui sont liées","Préserver le dialogue familial et prendre soin des parents et des aînés"],"synthese":"KA WO GBE réunit des enseignements liés à prospérité, famille, aînés et eau. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
