insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 214, 'signe_derive', null, '{"slug":"signe-213-ka-yekou","nom":"KA YEKOU","ordre":null,"type":"signe_derive","position":"213e signe du catalogue ; 197e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Ka ; signe dérivé de cette lignée","divinites":"Hoho, Kluvito, Tohossou","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["KA YEKOU appartient à la maison de Ka. Il occupe la 197e place parmi les 240 signes descendants.","Les protagonistes nommés sont Legba. Les images centrales du récit sont le marché, le pagne et le maïs. Son déroulement met en jeu une tension familiale qui révèle les devoirs de chacun puis une question d''autorité, de succession ou de gouvernement. La prospérité est possible, mais sa durée dépend d''une gestion honnête des biens et du respect des engagements pris. Une fonction d''autorité peut se présenter. Elle doit servir la communauté et s''exercer sans précipitation ni domination. La vie familiale constitue un lieu d''épreuve et d''accomplissement ; le dialogue, la fidélité et le respect des proches y sont déterminants.","L''eau marque une transformation : ce qui apporte la vie peut aussi surprendre une personne insuffisamment préparée. L''accomplissement des obligations indiquées est associé à l''apaisement, à la protection et au rétablissement de l''équilibre.","Son enseignement articule prospérité, autorité, famille et eau. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La richesse demande une conduite juste","sens":"L''abondance demeure favorable lorsqu''elle circule sans orgueil, tromperie ni abus de pouvoir."},{"ordre":2,"titre":"Le commandement se prouve par l''équité","sens":"Diriger engage la responsabilité du porteur envers ceux qui dépendent de ses décisions."},{"ordre":3,"titre":"La paix du foyer se construit","sens":"Les liens familiaux se consolident par la patience, la parole tenue et la protection réciproque."},{"ordre":4,"titre":"L''eau transforme ce qu''elle touche","sens":"Toute force bénéfique demande une juste préparation afin que son passage nourrisse au lieu de désorganiser."},{"ordre":5,"titre":"L''obligation accomplie rétablit l''équilibre","sens":"Le signe relie le mieux-être à une action concrète, menée avec sérieux et continuité."}],"interdits":["Écarter les comportements imprudents signalés par le signe"],"prescriptions":["Honorer Hoho et respecter les obligations qui lui sont liées","Honorer Kluvito et respecter les obligations qui lui sont liées","Honorer Tohossou et respecter les obligations qui lui sont liées","Préserver le dialogue familial et prendre soin des parents et des aînés"],"synthese":"KA YEKOU réunit des enseignements liés à prospérité, autorité, famille et eau. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
