insert into public.fa_signs (slug, name) values ('signe-229-tche-woli', 'TCHE WOLI') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 230, 'signe_derive', null, '{"slug":"signe-229-tche-woli","nom":"TCHE WOLI","ordre":null,"type":"signe_derive","position":"229e signe du catalogue ; 213e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Tchè ; signe dérivé de cette lignée","divinites":"Aucune divinité particulière n''est indiquée pour ce signe","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["TCHE WOLI appartient à la maison de Tchè. Il occupe la 213e place parmi les 240 signes descendants.","Les protagonistes nommés sont Sakpata. Son déroulement met en jeu une tension familiale qui révèle les devoirs de chacun. La vie familiale constitue un lieu d''épreuve et d''accomplissement ; le dialogue, la fidélité et le respect des proches y sont déterminants. Le signe appelle à se protéger des influences hostiles sans nourrir la peur ni répondre à l''agression par l''imprudence. L''accomplissement des obligations indiquées est associé à l''apaisement, à la protection et au rétablissement de l''équilibre.","Le porteur est invité à relire chaque décision à la lumière de la prudence, de la responsabilité et du respect de ses obligations.","Son enseignement articule famille, forces hostiles et obligations. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La paix du foyer se construit","sens":"Les liens familiaux se consolident par la patience, la parole tenue et la protection réciproque."},{"ordre":2,"titre":"La protection exige lucidité","sens":"La prudence, la discrétion et le respect des obligations forment une défense plus sûre que la provocation."},{"ordre":3,"titre":"L''obligation accomplie rétablit l''équilibre","sens":"Le signe relie le mieux-être à une action concrète, menée avec sérieux et continuité."}],"interdits":["Écarter les comportements imprudents signalés par le signe"],"prescriptions":["Préserver le dialogue familial et prendre soin des parents et des aînés"],"synthese":"TCHE WOLI réunit des enseignements liés à famille, forces hostiles et obligations. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
