insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 231, 'signe_derive', null, '{"slug":"signe-230-tche-di","nom":"TCHE-DI","ordre":null,"type":"signe_derive","position":"230e signe du catalogue ; 214e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Tchè ; signe dérivé de cette lignée","divinites":"Sakpata","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Le port de vêtements rouge est déconseillé.","profil":["TCHE-DI appartient à la maison de Tchè. Il occupe la 214e place parmi les 240 signes descendants.","L''enseignement part d''une situation ordinaire et en révèle les conséquences morales et spirituelles. Les rivalités annoncées doivent être contenues par la mesure, car une victoire obtenue dans la colère peut détruire l''équilibre du groupe. La vie familiale constitue un lieu d''épreuve et d''accomplissement ; le dialogue, la fidélité et le respect des proches y sont déterminants. L''eau marque une transformation : ce qui apporte la vie peut aussi surprendre une personne insuffisamment préparée.","Le signe appelle à se protéger des influences hostiles sans nourrir la peur ni répondre à l''agression par l''imprudence. L''accomplissement des obligations indiquées est associé à l''apaisement, à la protection et au rétablissement de l''équilibre.","Son enseignement articule conflit, famille, eau et forces hostiles. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"Deux forces opposées doivent retrouver la mesure","sens":"Le conflit devient fécond lorsque chacun renonce à l''escalade et recherche une solution juste."},{"ordre":2,"titre":"La paix du foyer se construit","sens":"Les liens familiaux se consolident par la patience, la parole tenue et la protection réciproque."},{"ordre":3,"titre":"L''eau transforme ce qu''elle touche","sens":"Toute force bénéfique demande une juste préparation afin que son passage nourrisse au lieu de désorganiser."},{"ordre":4,"titre":"La protection exige lucidité","sens":"La prudence, la discrétion et le respect des obligations forment une défense plus sûre que la provocation."},{"ordre":5,"titre":"L''obligation accomplie rétablit l''équilibre","sens":"Le signe relie le mieux-être à une action concrète, menée avec sérieux et continuité."}],"interdits":["Écarter les comportements imprudents signalés par le signe"],"prescriptions":["Accomplir avec sérieux les sacrifices et offrandes prescrits","Honorer Sakpata et respecter les obligations qui lui sont liées","Préserver le dialogue familial et prendre soin des parents et des aînés","Différer les décisions prises sous l''effet de la colère et rechercher l''apaisement"],"synthese":"TCHE-DI réunit des enseignements liés à conflit, famille, eau et forces hostiles. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
