select id, 232, 'signe_derive', null, '{"slug":"signe-231-tche-losso","nom":"TCHE-LOSSO","ordre":null,"type":"signe_derive","position":"231e signe du catalogue ; 215e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Tchè ; signe dérivé de cette lignée","divinites":"Hêviosso, Sakpata","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["TCHE-LOSSO appartient à la maison de Tchè. Il occupe la 215e place parmi les 240 signes descendants.","Les images centrales du récit sont l''oiseau et le maïs. La colère rapide est présentée comme une faiblesse dangereuse. Le porteur gagne à différer sa réaction et à retrouver son jugement. L''eau marque une transformation : ce qui apporte la vie peut aussi surprendre une personne insuffisamment préparée. Les relations d''amitié sont mises à l''épreuve. Le porteur doit distinguer la solidarité véritable d''une proximité intéressée.","L''accomplissement des obligations indiquées est associé à l''apaisement, à la protection et au rétablissement de l''équilibre.","Son enseignement articule colère, eau, amitié et obligations. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La colère ne doit pas décider","sens":"Prendre le temps de se calmer évite qu''une offense passagère produise un dommage durable."},{"ordre":2,"titre":"L''eau transforme ce qu''elle touche","sens":"Toute force bénéfique demande une juste préparation afin que son passage nourrisse au lieu de désorganiser."},{"ordre":3,"titre":"L''amitié se reconnaît dans l''épreuve","sens":"Un compagnon loyal protège et conseille ; une relation fondée sur l''intérêt se révèle lorsque survient le danger."},{"ordre":4,"titre":"L''obligation accomplie rétablit l''équilibre","sens":"Le signe relie le mieux-être à une action concrète, menée avec sérieux et continuité."}],"interdits":["Écarter les comportements imprudents signalés par le signe"],"prescriptions":["Honorer Hêviosso et respecter les obligations qui lui sont liées","Honorer Sakpata et respecter les obligations qui lui sont liées","Différer les décisions prises sous l''effet de la colère et rechercher l''apaisement"],"synthese":"TCHE-LOSSO réunit des enseignements liés à colère, eau, amitié et obligations. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
