insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 237, 'signe_derive', null, '{"slug":"signe-236-tchesa","nom":"TCHESA","ordre":null,"type":"signe_derive","position":"236e signe du catalogue ; 220e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Tchesa ; signe dérivé de cette lignée","divinites":"Dan, Sakpata","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["TCHESA appartient à la maison de Tchesa. Il occupe la 220e place parmi les 240 signes descendants.","Son déroulement met en jeu une épreuve où la vie et la mort sont mises en balance. Le signe place la préservation de la vie au premier plan et demande de reconnaître le danger avant qu''il ne devienne irréversible. Une confiance mal placée peut exposer le porteur à la ruse ou à la trahison ; il lui faut observer les actes autant que les paroles. Les rivalités annoncées doivent être contenues par la mesure, car une victoire obtenue dans la colère peut détruire l''équilibre du groupe.","Une fonction d''autorité peut se présenter. Elle doit servir la communauté et s''exercer sans précipitation ni domination. La vie familiale constitue un lieu d''épreuve et d''accomplissement ; le dialogue, la fidélité et le respect des proches y sont déterminants.","Son enseignement articule danger, trahison, conflit et autorité. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La vigilance protège la vie","sens":"Le danger perd une part de sa force lorsqu''il est reconnu tôt et traité avec calme."},{"ordre":2,"titre":"La confiance se donne avec discernement","sens":"La loyauté se vérifie dans les actes. Le signe invite à rester ouvert sans ignorer les indices d''une intention cachée."},{"ordre":3,"titre":"Deux forces opposées doivent retrouver la mesure","sens":"Le conflit devient fécond lorsque chacun renonce à l''escalade et recherche une solution juste."},{"ordre":4,"titre":"Le commandement se prouve par l''équité","sens":"Diriger engage la responsabilité du porteur envers ceux qui dépendent de ses décisions."},{"ordre":5,"titre":"La paix du foyer se construit","sens":"Les liens familiaux se consolident par la patience, la parole tenue et la protection réciproque."}],"interdits":["Écarter les comportements imprudents signalés par le signe"],"prescriptions":["Honorer Dan et respecter les obligations qui lui sont liées","Honorer Sakpata et respecter les obligations qui lui sont liées","Préserver le dialogue familial et prendre soin des parents et des aînés","Différer les décisions prises sous l''effet de la colère et rechercher l''apaisement"],"synthese":"TCHESA réunit des enseignements liés à danger, trahison, conflit et autorité. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
