select id, 238, 'signe_derive', null, '{"slug":"signe-237-tche-trukpin","nom":"TCHE TRUKPIN","ordre":null,"type":"signe_derive","position":"237e signe du catalogue ; 221e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Tchè ; signe dérivé de cette lignée","divinites":"Sakpata","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["TCHE TRUKPIN appartient à la maison de Tchè. Il occupe la 221e place parmi les 240 signes descendants.","Les images centrales du récit sont le champ. Les rivalités annoncées doivent être contenues par la mesure, car une victoire obtenue dans la colère peut détruire l''équilibre du groupe. Le résultat annoncé dépend d''un effort régulier. La patience et la constance valent davantage qu''une réussite recherchée dans la précipitation. L''accomplissement des obligations indiquées est associé à l''apaisement, à la protection et au rétablissement de l''équilibre.","Le porteur est invité à relire chaque décision à la lumière de la prudence, de la responsabilité et du respect de ses obligations.","Son enseignement articule conflit, travail et obligations. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"Deux forces opposées doivent retrouver la mesure","sens":"Le conflit devient fécond lorsque chacun renonce à l''escalade et recherche une solution juste."},{"ordre":2,"titre":"Le travail patient porte son fruit","sens":"Une œuvre durable se construit par des gestes répétés, ordonnés et conduits jusqu''à leur terme."},{"ordre":3,"titre":"L''obligation accomplie rétablit l''équilibre","sens":"Le signe relie le mieux-être à une action concrète, menée avec sérieux et continuité."}],"interdits":["Écarter les comportements imprudents signalés par le signe"],"prescriptions":["Honorer Sakpata et respecter les obligations qui lui sont liées","Différer les décisions prises sous l''effet de la colère et rechercher l''apaisement"],"synthese":"TCHE TRUKPIN réunit des enseignements liés à conflit, travail et obligations. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
