insert into public.fa_signs (slug, name) values ('signe-238-tche-toula', 'TCHE TOULA') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 239, 'signe_derive', null, '{"slug":"signe-238-tche-toula","nom":"TCHE TOULA","ordre":null,"type":"signe_derive","position":"238e signe du catalogue ; 222e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Tchè ; signe dérivé de cette lignée","divinites":"Lègba","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["TCHE TOULA appartient à la maison de Tchè. Il occupe la 222e place parmi les 240 signes descendants.","Les images centrales du récit sont l''oiseau, le pagne et le maïs. Son déroulement met en jeu une consultation destinée à éclairer une décision, une épreuve où la vie et la mort sont mises en balance puis une manœuvre cachée qui met la loyauté à l''épreuve. Le signe place la préservation de la vie au premier plan et demande de reconnaître le danger avant qu''il ne devienne irréversible. Une confiance mal placée peut exposer le porteur à la ruse ou à la trahison ; il lui faut observer les actes autant que les paroles. Une fonction d''autorité peut se présenter. Elle doit servir la communauté et s''exercer sans précipitation ni domination.","La parole possède ici un pouvoir particulier : une confidence révélée, une promesse rompue ou un propos irréfléchi peut bouleverser une destinée. L''eau marque une transformation : ce qui apporte la vie peut aussi surprendre une personne insuffisamment préparée.","Son enseignement articule danger, trahison, autorité et parole. Les interdits et prescriptions précisent la conduite à tenir pour préserver l''équilibre recherché."],"devises":[{"ordre":1,"titre":"La vigilance protège la vie","sens":"Le danger perd une part de sa force lorsqu''il est reconnu tôt et traité avec calme."},{"ordre":2,"titre":"La confiance se donne avec discernement","sens":"La loyauté se vérifie dans les actes. Le signe invite à rester ouvert sans ignorer les indices d''une intention cachée."},{"ordre":3,"titre":"Le commandement se prouve par l''équité","sens":"Diriger engage la responsabilité du porteur envers ceux qui dépendent de ses décisions."},{"ordre":4,"titre":"La parole mesurée préserve","sens":"Le silence et la discrétion protègent ce qui doit mûrir avant d''être rendu public."},{"ordre":5,"titre":"L''eau transforme ce qu''elle touche","sens":"Toute force bénéfique demande une juste préparation afin que son passage nourrisse au lieu de désorganiser."}],"interdits":["Écarter les comportements imprudents signalés par le signe"],"prescriptions":["Honorer Lègba et respecter les obligations qui lui sont liées","Garder les confidences et mesurer toute parole donnée"],"synthese":"TCHE TOULA réunit des enseignements liés à danger, trahison, autorité et parole. Le porteur doit agir avec discernement, respecter les interdits associés au signe et accomplir ses obligations afin de favoriser protection, stabilité et accomplissement."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
