insert into public.fa_signs (slug, name) values ('signe-253-fu-tula', 'FU TULA') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 254, 'signe_derive', null, '{"slug":"signe-253-fu-tula","nom":"FU TULA","ordre":null,"type":"signe_derive","position":"253e signe du catalogue ; 237e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Fu ; signe dérivé de cette lignée","divinites":"Fa, Ori et Lègba","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["FU TULA appartient à la maison de Fu. Il occupe la 237e place parmi les 240 signes descendants.","Fu Tula associe l''accomplissement à une orientation claire de la destinée. Il demande de renforcer régulièrement ce qui a été commencé au lieu d''attendre qu''une difficulté oblige à agir.","La parole peut aller plus vite que la pensée. Le porteur doit donc vérifier ses informations, tenir ses engagements et éviter de décider sous l''effet d''une inquiétude passagère.","L''attention portée au corps, à l''alimentation et aux relations intimes participe à la protection. L''écoute de la famille et des personnes expérimentées aide à ne pas s''égarer."],"devises":[{"ordre":1,"titre":"La parole ne doit pas devancer la pensée","sens":"Vérifier avant d''affirmer protège la réputation et empêche une erreur de devenir publique."},{"ordre":2,"titre":"La destinée se renforce par des actes continus","sens":"Une obligation régulièrement entretenue soutient mieux le parcours qu''une action tardive menée dans l''urgence."},{"ordre":3,"titre":"Le conseil des proches garde la route","sens":"L''expérience familiale peut révéler un risque que l''ambition ou la peur empêchait de voir."}],"interdits":["Parler avant d''avoir vérifié les faits","Négliger les avertissements concernant la santé","Rompre une prescription suivie dans la durée"],"prescriptions":["Entretenir régulièrement les offrandes prescrites","Honorer Fa, Ori et Lègba","Écouter les conseils fiables de la famille avant une décision majeure"],"synthese":"FU TULA développe des thèmes liés à destinée, parole, santé, continuité des offrandes et responsabilité. Le porteur doit respecter ses interdits, accomplir les obligations indiquées et conduire ses choix avec mesure afin de préserver son équilibre."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
from public.fa_signs where slug = 'signe-253-fu-tula'
