insert into public.fa_signs (slug, name) values ('signe-254-fu-lete', 'FU LETE') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 255, 'signe_derive', null, '{"slug":"signe-254-fu-lete","nom":"FU LETE","ordre":null,"type":"signe_derive","position":"254e signe du catalogue ; 238e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Fu ; signe dérivé de cette lignée","divinites":"Fa, Ori, Lissa et Kluvito","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["FU LETE appartient à la maison de Fu. Il occupe la 238e place parmi les 240 signes descendants.","Fu Lètè met la prudence au service de l''accomplissement. Il rappelle que la dimension spirituelle et la conduite quotidienne ne peuvent être séparées.","Le signe déconseille l''indiscrétion, la désobéissance et la recherche excessive de richesse. Il invite aussi à examiner une situation avant d''agir et à prendre au sérieux les troubles persistants de la santé.","Le porteur gagne à entretenir des relations utiles avec la communauté, à rechercher la réconciliation lorsqu''un lien est rompu et à terminer soigneusement ce qu''il entreprend."],"devises":[{"ordre":1,"titre":"S''informer d''abord, agir ensuite","sens":"L''enquête patiente protège des erreurs produites par la rumeur, l''apparence ou l''indiscrétion."},{"ordre":2,"titre":"L''âme donne au corps son orientation","sens":"La vie intérieure soutient la dignité, la santé et la capacité de traverser une épreuve."},{"ordre":3,"titre":"La prudence ouvre l''air de la longévité","sens":"La modération dans les ambitions et les habitudes protège une réussite déjà acquise."}],"interdits":["Agir sur une information non vérifiée","Révéler une confidence","Poursuivre la richesse au détriment de la santé","Désobéir à un avertissement important"],"prescriptions":["Honorer Fa, Ori, Lissa et Kluvito","Prendre en charge sans retard les troubles de santé persistants","Rechercher la réconciliation et achever les obligations commencées"],"synthese":"FU LETE développe des thèmes liés à prudence, spiritualité, santé, reconnaissance et réconciliation. Le porteur doit respecter ses interdits, accomplir les obligations indiquées et conduire ses choix avec mesure afin de préserver son équilibre."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
