insert into public.fa_signs (slug, name) values ('signe-255-fu-tche', 'FU TCHE') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 256, 'signe_derive', null, '{"slug":"signe-255-fu-tche","nom":"FU TCHE","ordre":null,"type":"signe_derive","position":"255e signe du catalogue ; 239e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Fu ; signe dérivé de cette lignée","divinites":"Fa et Ori","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["FU TCHE appartient à la maison de Fu. Il occupe la 239e place parmi les 240 signes descendants.","Fu Tchè porte un enseignement d''achèvement. Une étape doit être comprise, menée à son terme et libérée avant qu''un nouveau commencement puisse devenir solide.","L''image de l''oiseau calme au milieu des turbulences invite à conserver dignité et maîtrise de soi. Les revers ne doivent conduire ni à l''abandon ni à une réaction désordonnée.","Le porteur progresse par des actions délibérées, des sacrifices accomplis et un effort continu. Il doit aussi renoncer à l''alcool lorsque celui-ci affaiblit sa lucidité et sa constance."],"devises":[{"ordre":1,"titre":"Achever prépare le nouveau commencement","sens":"Une transition devient féconde lorsque les obligations anciennes sont réglées avec clarté."},{"ordre":2,"titre":"La dignité demeure au milieu de la turbulence","sens":"Le calme permet de protéger son jugement et de choisir une réponse proportionnée à l''épreuve."},{"ordre":3,"titre":"La persévérance traverse le revers","sens":"L''effort continu transforme une difficulté temporaire en apprentissage et en nouvelle possibilité."}],"interdits":["Consommer de l''alcool","Abandonner une étape sans régler ses obligations","Réagir dans la confusion ou la précipitation"],"prescriptions":["Accomplir les sacrifices prescrits","Honorer Fa et Ori","Clore les engagements anciens avant d''ouvrir un nouveau cycle"],"synthese":"FU TCHE développe des thèmes liés à achèvement, dignité, patience, persévérance et nouveau départ. Le porteur doit respecter ses interdits, accomplir les obligations indiquées et conduire ses choix avec mesure afin de préserver son équilibre."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
