insert into public.fa_signs (slug, name) values ('signe-256-fu-ka', 'FU KA') on conflict (slug) do nothing;

insert into public.fa_sign_documents (fa_sign_id, catalog_slot, kind, mother_order, content, source, status)
select id, 257, 'signe_derive', null, '{"slug":"signe-256-fu-ka","nom":"FU KA","ordre":null,"type":"signe_derive","position":"256e signe du catalogue ; 240e des 240 signes descendants","sexeSymbolique":"Non précisé pour ce signe","maison":"Maison de Fu ; signe dérivé de cette lignée","divinites":"Fa, Lissa et Sakpata","feuilles":"Aucune feuille particulière n''est indiquée pour ce signe","couleurs":"Aucune couleur particulière n''est indiquée pour ce signe.","profil":["FU KA appartient à la maison de Fu. Il occupe la 240e place parmi les 240 signes descendants.","Fu Ka met en scène le renversement des positions : une personne utile peut être exploitée ou privée de reconnaissance, avant que la vérité de son travail n''apparaisse.","Le signe demande de respecter les aînés comme les plus jeunes, d''éviter les gains douteux et de ne pas prétendre maîtriser un savoir que l''on ne possède pas. L''orgueil et la tromperie affaiblissent la protection.","La propreté du foyer, la fidélité aux règles morales et le soin accordé aux proches constituent une discipline quotidienne. L''humilité permet au porteur de recevoir l''aide annoncée sans répéter les erreurs passées."],"devises":[{"ordre":1,"titre":"Le service oublié finit par révéler sa valeur","sens":"Le manque de reconnaissance ne supprime pas la qualité d''une œuvre ; la constance prépare son rétablissement."},{"ordre":2,"titre":"L''argent injuste porte son propre désordre","sens":"Un gain obtenu sans éthique expose le foyer à des conséquences plus lourdes que son avantage immédiat."},{"ordre":3,"titre":"Le savoir véritable reste humble","sens":"Reconnaître ses limites protège des erreurs et permet de demander conseil à une personne compétente."}],"interdits":["Accepter un gain obtenu de manière douteuse","Tromper une personne qui demande conseil","Révéler un secret confié","Mépriser les aînés ou les personnes vulnérables"],"prescriptions":["Honorer Fa, Lissa et Sakpata","Maintenir la maison et les objets rituels dans la propreté","Agir avec humilité, intégrité et respect envers chaque génération"],"synthese":"FU KA développe des thèmes liés à respect, intégrité, prudence financière, humilité et protection du foyer. Le porteur doit respecter ses interdits, accomplir les obligations indiquées et conduire ses choix avec mesure afin de préserver son équilibre."}'::jsonb, '{"titre":"Bibliothèque Ifawa","version":"2026-09-27"}'::jsonb, 'published'
